  const imgRatio = img.width / img.height
  const pageRatio = w / h
  let dw = w
  let dh = h
  if (imgRatio > pageRatio) {
    dh = w / imgRatio
  } else {
    dw = h * imgRatio
  }
  return { x: (w - dw) / 2, y: (h - dh) / 2, width: dw, height: dh }
}

