export async function generateQrPng(text: string): Promise<Uint8Array> {
  return QRCode.toBuffer(text, { type: 'png', width: 400, margin: 1, errorCorrectionLevel: 'M' })
}

interface GenerateReceiptInput {
  donationId: string
  templateId?: string
  trust: Trust
  donation: Donation
  collector?: TrustMember | null
  actorId?: string | null
}

export async function getNextReceiptNumber(trustId: string, year: string): Promise<string> {
  return prisma.$transaction(async (tx) => {
    let cfg = await tx.receiptNumberConfig.findUnique({
      where: { trustId_prefix_year: { trustId, prefix: 'RC', year } },
    })
    if (!cfg) {
      cfg = await tx.receiptNumberConfig.create({
        data: { trustId, prefix: 'RC', year, nextSequence: 1, padLength: 6 },
      })
    }
    const seq = cfg.nextSequence
    await tx.receiptNumberConfig.update({
      where: { id: cfg.id },
      data: { nextSequence: seq + 1 },
    })
    const padded = String(seq).padStart(cfg.padLength, '0')
    return `${cfg.prefix}${cfg.separator}${year}${cfg.separator}${padded}`
  })
}

export async function generateReceipt(input: GenerateReceiptInput): Promise<{ id: string; receiptNumber: string; pdfUrl: string; verificationToken: string }> {
  const { donation, trust } = input

  const template = input.templateId
    ? await prisma.receiptTemplate.findUnique({ where: { id: input.templateId } })
    : await prisma.receiptTemplate.findFirst({ where: { trustId: trust.id, active: true } })

  if (!template) {
    throw new AppError(400, 'No receipt template configured. Please create and activate a Pāvati template first.')
  }

  const templateView: ReceiptTemplateView = {
    id: template.id,
    name: template.name,
    pageSize: template.pageSize,
    widthMm: template.widthMm,
    heightMm: template.heightMm,
    backgroundImageUrl: template.backgroundImageUrl,
    fieldConfigs: (template.fieldConfigs as never as Parameters<typeof renderReceiptPdf>[0]['template']['fieldConfigs']) ?? [],
  }

  const year = new Date(donation.donationDate).getFullYear().toString()
  const receiptNumber = await getNextReceiptNumber(trust.id, year)

  const verificationToken = randomBytes(16).toString('hex')
  const verificationUrl = `${config.publicBaseUrl}/receipt/verify/${verificationToken}`

  const background = template.backgroundImageUrl ? fileFromUrl(template.backgroundImageUrl)?.buffer ?? null : null
  const logo = trust.logoUrl ? fileFromUrl(trust.logoUrl)?.buffer ?? null : null
  const qr = await generateQrPng(verificationUrl)

  const data: ReceiptData = {
    trustName: trust.name,
    trustAddress: [trust.address, trust.city, trust.pinCode].filter(Boolean).join(', '),
    receiptNumber,
    receiptDate: donation.donationDate.toISOString(),
    donorName: donation.donorName,
    donorPhone: donation.phone ?? undefined,
    donorAddress: donation.address ?? undefined,
    amount: donation.amount,
    paymentMode: donation.paymentMode,
    category: donation.category,
    transactionRef: donation.transactionRef ?? undefined,
    collectorName: input.collector ? `${input.collector.position || ''} ${input.collector.user?.name ?? ''}`.trim() : undefined,
    footerText: `धन्यवाद — Thank you for your generous support`,
  }

  try {
    const pdfBytes = await renderReceiptPdf({
      template: templateView,
      data,
      background,
      logo,
      qr,
    })
    const stored = await savePdf(pdfBytes, `receipts/${trust.id}`)

    const receipt = await prisma.receipt.create({
      data: {
        receiptNumber,
        donationId: donation.id,
        trustId: trust.id,
        templateId: template.id,
        pdfUrl: stored.url,
        verificationToken,
      },
    })

    return {
      id: receipt.id,
      receiptNumber,
      pdfUrl: stored.url,
      verificationToken,
    }
  } catch (e) {
    logger.error({ err: e }, 'PDF generation failed')
    throw new AppError(500, 'Failed to generate receipt PDF')
  }
}

export async function verifyReceiptData(token: string) {
  const receipt = await prisma.receipt.findUnique({
    where: { verificationToken: token },
    include: { donation: { include: { trust: true } }, trust: true },
  })
  if (!receipt) return null
  const privacy = receipt.donation.privacy
  return {
    verified: receipt.status === 'ACTIVE',
    receiptNumber: receipt.receiptNumber,
    trustName: receipt.trust.name,
    donationDate: receipt.donation.donationDate,
    amount: receipt.donation.amount,
    donorName: privacy === 'ANONYMOUS' ? 'Anonymous Donor' : receipt.donation.donorName,
    status: receipt.status,
  }
}

import type { User } from '@prisma/client'
import { prisma } from './prisma.js'
import { publicUser, signAccessToken, signRefreshToken } from './jwt.js'

export async function buildAuthResponse(user: User) {
  const memberships = await prisma.trustMember.findMany({
    where: { userId: user.id, status: 'ACTIVE' },
    include: { trust: true },
    orderBy: { joinedAt: 'asc' },
  })
  return {
    accessToken: signAccessToken(user.id),
    refreshToken: signRefreshToken(user.id),
    user: publicUser(user),
    memberships: memberships.map((m) => ({
      id: m.id,
      trustId: m.trustId,
      role: m.role,
      status: m.status,
      joinedAt: m.joinedAt,
      trust: {
        id: m.trust.id,
        name: m.trust.name,
        uniqueCode: m.trust.uniqueCode,
        logoUrl: m.trust.logoUrl,
        festivalTypes: m.trust.festivalTypes,
        city: m.trust.city,
      },
    })),
  }
}

export async function createRefreshRecord(userId: string, refreshToken: string) {
  const crypto = await import('node:crypto')
  await prisma.refreshToken.create({
    data: {
      tokenHash: crypto.createHash('sha256').update(refreshToken).digest('hex'),
      userId,
      expiresAt: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000),
    },
  })
}

import { Router } from 'express'
import bcrypt from 'bcryptjs'
import crypto from 'node:crypto'
import jwt from 'jsonwebtoken'
import { prisma } from '../../lib/prisma.js'
import { AppError, asyncHandler, ok } from '../../lib/http.js'
import { requireAuth, type AuthedRequest } from '../../middleware/auth.js'
import { validateBody } from '../../middleware/validate.js'
import { authRateLimiter, otpRateLimiter } from '../../middleware/rateLimit.js'
import {
  forgotPasswordSchema,
  googleAuthSchema,
  loginSchema,
  registerSchema,
  requestOtpSchema,
  resetPasswordSchema,
  verifyOtpSchema,
} from '@pavati/shared'
import { config } from '../../config/index.js'
import { otpProvider } from '../../providers/otp.js'
import { publicUser, verifyRefreshToken } from '../../lib/jwt.js'
import { buildAuthResponse, createRefreshRecord } from '../../lib/session.js'
import { audit } from '../../services/audit.js'

const router = Router()

async function findOrCreateUser(data: { phone?: string; email?: string; name: string; authProvider: 'PHONE' | 'EMAIL' | 'GOOGLE'; profileImage?: string | null }) {
  let user = data.phone
    ? await prisma.user.findUnique({ where: { phone: data.phone } })
    : data.email
      ? await prisma.user.findUnique({ where: { email: data.email } })
      : null
  if (!user) {
    user = await prisma.user.create({
      data: {
        name: data.name,
        phone: data.phone ?? null,
        email: data.email ?? null,
        authProvider: data.authProvider,
        profileImage: data.profileImage ?? null,
      },
    })
    await audit({ actorId: user.id, action: 'REGISTER' })
  }
  return user
}

router.post(
  '/register',
  authRateLimiter(),
  validateBody(registerSchema),
  asyncHandler(async (req, res) => {
    const { name, email, password, phone } = req.body
    const existing = await prisma.user.findFirst({ where: { OR: [{ email }, ...(phone ? [{ phone }] : [])] } })
    if (existing) throw new AppError(409, 'An account with this email or phone already exists')
    const passwordHash = await bcrypt.hash(password, 10)
    const user = await prisma.user.create({
      data: { name, email, passwordHash, phone: phone || null, authProvider: 'EMAIL' },
    })
    await audit({ actorId: user.id, action: 'REGISTER' })
    const session = await buildAuthResponse(user)
    await createRefreshRecord(user.id, session.refreshToken)
    ok(res, session, 201)
  })
)

router.post(
  '/login',
  authRateLimiter(),
  validateBody(loginSchema),
  asyncHandler(async (req, res) => {
    const { email, password } = req.body
    const user = await prisma.user.findUnique({ where: { email } })
    if (!user?.passwordHash || !(await bcrypt.compare(password, user.passwordHash))) {
      throw new AppError(401, 'Invalid email or password')
    }
    await audit({ actorId: user.id, action: 'LOGIN' })
    const session = await buildAuthResponse(user)
    await createRefreshRecord(user.id, session.refreshToken)
    ok(res, session)
  })
)

router.post(
  '/phone/request-otp',
  otpRateLimiter(),
  validateBody(requestOtpSchema),
  asyncHandler(async (req, res) => {
    const { phone } = req.body
    const otp = otpProvider.generate()
    const codeHash = crypto.createHash('sha256').update(otp).digest('hex')
    await prisma.otpCode.deleteMany({ where: { phone, purpose: 'LOGIN' } })
    await prisma.otpCode.create({
      data: { phone, codeHash, purpose: 'LOGIN', expiresAt: new Date(Date.now() + 5 * 60 * 1000) },
    })
    const sent = await otpProvider.send(phone, otp)
    ok(res, {
      message: 'OTP sent',
      expiresIn: 300,
      ...(config.mockMode ? { devOtp: sent.devCode } : {}),
    })
  })
)

router.post(
  '/phone/verify',
  authRateLimiter(),
  validateBody(verifyOtpSchema),
  asyncHandler(async (req, res) => {
    const { phone, otp } = req.body
    const record = await prisma.otpCode.findFirst({
      where: { phone, purpose: 'LOGIN', consumed: false },
      orderBy: { createdAt: 'desc' },
    })
    if (!record) throw new AppError(400, 'No OTP request found. Please request a new OTP.')
    if (record.expiresAt < new Date()) throw new AppError(400, 'OTP expired. Please request a new one.')
    const hash = crypto.createHash('sha256').update(otp).digest('hex')
    if (hash !== record.codeHash) {
      await prisma.otpCode.update({ where: { id: record.id }, data: { attempts: { increment: 1 } } })
      throw new AppError(400, 'Invalid OTP')
    }
    await prisma.otpCode.update({ where: { id: record.id }, data: { consumed: true } })
    const user = await findOrCreateUser({ phone, name: 'New User', authProvider: 'PHONE' })
    const session = await buildAuthResponse(user)
    await createRefreshRecord(user.id, session.refreshToken)
    ok(res, session)
  })
)

router.post(
  '/google',
  authRateLimiter(),
  validateBody(googleAuthSchema),
  asyncHandler(async (req, res) => {
    const { profile } = req.body
    const email = profile?.email ?? `${req.body.idToken.slice(0, 12)}@mock.google`
    const user = await findOrCreateUser({
      email,
      name: profile?.name ?? 'Google User',
      authProvider: 'GOOGLE',
      profileImage: profile?.picture ?? null,
    })
    const session = await buildAuthResponse(user)
    await createRefreshRecord(user.id, session.refreshToken)
    ok(res, session)
  })
)

router.post(
  '/forgot-password',
  authRateLimiter(),
  validateBody(forgotPasswordSchema),
  asyncHandler(async (req, res) => {
    const { email } = req.body
    const user = await prisma.user.findUnique({ where: { email } })
    if (user) {
      const token = jwt.sign({ sub: user.id, type: 'reset' }, config.jwtSecret, { expiresIn: '30m' })
      const resetUrl = `${config.webOrigin}/reset-password?token=${token}`
      if (config.mockMode) {
        ok(res, { message: 'Password reset link sent', devResetUrl: resetUrl })
        return
      }
    }
    ok(res, { message: 'If an account exists with that email, a reset link has been sent.' })
  })
)

router.post(
  '/reset-password',
  authRateLimiter(),
  validateBody(resetPasswordSchema),
  asyncHandler(async (req, res) => {
    const { token, password } = req.body
    let payload: { sub: string; type: string }
    try {
      payload = jwt.verify(token, config.jwtSecret) as { sub: string; type: string }
    } catch {
      throw new AppError(400, 'Invalid or expired reset token')
    }
    if (payload.type !== 'reset') throw new AppError(400, 'Invalid token')
    const passwordHash = await bcrypt.hash(password, 10)
    await prisma.user.update({ where: { id: payload.sub }, data: { passwordHash } })
    ok(res, { message: 'Password updated. You can now log in.' })
  })
)

router.post(
  '/refresh',
  authRateLimiter(),
  asyncHandler(async (req, res) => {
    const token = req.body?.refreshToken as string | undefined
    if (!token) throw new AppError(401, 'Refresh token required')
    const payload = verifyRefreshToken(token)
    if (payload.type !== 'refresh') throw new AppError(401, 'Invalid token type')
    const hash = crypto.createHash('sha256').update(token).digest('hex')
    const record = await prisma.refreshToken.findFirst({ where: { tokenHash: hash, revoked: false } })
    if (!record || record.expiresAt < new Date()) throw new AppError(401, 'Refresh token revoked or expired')
    const user = await prisma.user.findUnique({ where: { id: payload.sub } })
    if (!user) throw new AppError(401, 'User not found')
    const session = await buildAuthResponse(user)
    await prisma.refreshToken.update({ where: { id: record.id }, data: { revoked: true } })
    await createRefreshRecord(user.id, session.refreshToken)
    ok(res, session)
  })
)

router.post(
  '/logout',
  asyncHandler(async (req, res) => {
    const token = req.body?.refreshToken as string | undefined
    if (token) {
      const hash = crypto.createHash('sha256').update(token).digest('hex')
      await prisma.refreshToken.updateMany({ where: { tokenHash: hash }, data: { revoked: true } })
    }
    ok(res, { message: 'Logged out' })
  })
)

router.get(
  '/me',
  requireAuth,
  asyncHandler(async (req: AuthedRequest, res) => {
    const memberships = await prisma.trustMember.findMany({
      where: { userId: req.user!.id, status: 'ACTIVE' },
      include: { trust: true },
    })
    ok(res, {
      user: publicUser(req.user!),
      memberships: memberships.map((m) => ({
        id: m.id,
        trustId: m.trustId,
        role: m.role,
        trust: { id: m.trust.id, name: m.trust.name, logoUrl: m.trust.logoUrl, uniqueCode: m.trust.uniqueCode, festivalTypes: m.trust.festivalTypes, city: m.trust.city },
      })),
    })
  })
)

export default router

import { Router } from 'express'
import { prisma } from '../../lib/prisma.js'
import { AppError, asyncHandler, ok } from '../../lib/http.js'
import { requireAuth, type AuthedRequest } from '../../middleware/auth.js'
import { loadTrustContext, requirePermission, type TrustContextRequest } from '../../middleware/rbac.js'
import { validateBody, validateParams } from '../../middleware/validate.js'
import { createTrustSchema, joinByCodeSchema, updateTrustSchema, z, randomCode } from '@pavati/shared'
import { audit } from '../../services/audit.js'
import { publicUser } from '../../lib/jwt.js'

const router = Router()

function buildCodes(name: string): { uniqueCode: string; joinCode: string } {
  const word = name.replace(/[^a-zA-Z0-9]/g, '').slice(0, 6).toUpperCase() || 'TRUST'
  const year = new Date().getFullYear()
  return {
    uniqueCode: `${word}${year}`,
    joinCode: `${word}${year}${randomCode(3)}`,
  }
}

router.post(
  '/',
  requireAuth,
  validateBody(createTrustSchema),
  asyncHandler(async (req: AuthedRequest, res) => {
    const body = req.body
    const { uniqueCode, joinCode } = buildCodes(body.name)
    const trust = await prisma.trust.create({
      data: {
        name: body.name,
        uniqueCode,
        joinCode,
        logoUrl: body.logoUrl ?? null,
        festivalTypes: body.festivalTypes,
        description: body.description ?? null,
        registrationNumber: body.registrationNumber ?? null,
        address: body.address ?? null,
        city: body.city ?? null,
        state: body.state ?? null,
        country: body.country ?? null,
        pinCode: body.pinCode ?? null,
        contactPhone: body.contactPhone ?? null,
        contactEmail: body.contactEmail ?? null,
        website: body.website ?? null,
        upiId: body.upiId ?? null,
        financialYear: body.financialYear ?? null,
        festivalStartDate: body.festivalStartDate ? new Date(body.festivalStartDate) : null,
        festivalEndDate: body.festivalEndDate ? new Date(body.festivalEndDate) : null,
        joinMode: body.joinMode,
      },
    })
    const member = await prisma.trustMember.create({
      data: { trustId: trust.id, userId: req.user!.id, role: 'PRIMARY_ADMIN' },
    })
    await audit({ actorId: req.user!.id, trustId: trust.id, action: 'TRUST_CREATED', entityType: 'Trust', entityId: trust.id, metadata: { name: trust.name } })
    ok(res, { trust, member, joinCode: trust.joinCode, uniqueCode: trust.uniqueCode }, 201)
  })
)

router.get(
  '/search',
  asyncHandler(async (req, res) => {
    const q = String(req.query.q ?? '').trim()
    const city = String(req.query.city ?? '').trim()
    const where: Record<string, unknown> = {}
    if (q) where.OR = [{ name: { contains: q, mode: 'insensitive' } }, { description: { contains: q, mode: 'insensitive' } }]
    if (city) where.city = { contains: city, mode: 'insensitive' }
    const trusts = await prisma.trust.findMany({
      where,
      include: { _count: { select: { members: true } } },
      take: 50,
      orderBy: { createdAt: 'desc' },
    })
    ok(res, trusts.map((t) => ({ id: t.id, name: t.name, uniqueCode: t.uniqueCode, logoUrl: t.logoUrl, festivalTypes: t.festivalTypes, description: t.description, city: t.city, state: t.state, memberCount: t._count.members, joinMode: t.joinMode })))
  })
)

router.get(
  '/by-code/:code',
  validateParams(z.object({ code: z.string().min(3).max(20) })),
  asyncHandler(async (req, res) => {
    const trust = await prisma.trust.findFirst({
      where: { joinCode: { equals: req.params.code, mode: 'insensitive' } },
      include: { _count: { select: { members: true } } },
    })
    if (!trust) throw new AppError(404, 'Trust not found for this code')
    ok(res, { id: trust.id, name: trust.name, uniqueCode: trust.uniqueCode, logoUrl: trust.logoUrl, festivalTypes: trust.festivalTypes, description: trust.description, city: trust.city, state: trust.state, memberCount: trust._count.members, joinMode: trust.joinMode })
  })
)

router.get(
  '/:trustId',
  asyncHandler(async (req: TrustContextRequest, res) => {
    const trust = await prisma.trust.findUnique({
      where: { id: req.params.trustId },
      include: { _count: { select: { members: true } } },
    })
    if (!trust) throw new AppError(404, 'Trust not found')
    const committee = trust.showCommitteePublicly
      ? await prisma.trustMember.findMany({
          where: { trustId: trust.id, status: 'ACTIVE', role: { in: ['PRIMARY_ADMIN', 'ADMIN', 'PRESIDENT', 'VICE_PRESIDENT', 'SECRETARY', 'JOINT_SECRETARY', 'TREASURER'] } },
          include: { user: true },
        })
      : []
    const donations = trust.showDonorsPublicly
      ? await prisma.donation.findMany({
          where: { trustId: trust.id, status: 'SUCCEEDED', privacy: 'PUBLIC' },
          orderBy: { donationDate: 'desc' },
          take: 100,
        })
      : []
    ok(res, {
      id: trust.id,
      name: trust.name,
      uniqueCode: trust.uniqueCode,
      joinCode: trust.joinCode,
      logoUrl: trust.logoUrl,
      festivalTypes: trust.festivalTypes,
      description: trust.description,
      registrationNumber: trust.registrationNumber,
      address: trust.address,
      city: trust.city,
      state: trust.state,
      country: trust.country,
      pinCode: trust.pinCode,
      contactPhone: trust.contactPhone,
      contactEmail: trust.contactEmail,
      website: trust.website,
      upiId: trust.upiId,
      financialYear: trust.financialYear,
      festivalStartDate: trust.festivalStartDate,
      festivalEndDate: trust.festivalEndDate,
      joinMode: trust.joinMode,
      showCommitteePublicly: trust.showCommitteePublicly,
      showDonorsPublicly: trust.showDonorsPublicly,
      showDonationAmounts: trust.showDonationAmounts,
      allowAnonymousDonations: trust.allowAnonymousDonations,
      memberCount: trust._count.members,
      committee: committee.map((m) => ({ id: m.id, role: m.role, position: m.position, contactVisible: m.contactVisible, introduction: m.introduction, user: m.contactVisible ? publicUser(m.user) : { id: m.user.id, name: m.user.name, profileImage: m.user.profileImage } })),
      recentDonations: donations.map((d) => ({ id: d.id, donorName: d.privacy === 'ANONYMOUS' ? 'Anonymous Donor' : d.donorName, amount: trust.showDonationAmounts ? d.amount : null, donationDate: d.donationDate, category: d.category })),
    })
  })
)

router.post(
  '/:trustId/join',
  requireAuth,
  validateBody(joinByCodeSchema),
  asyncHandler(async (req: AuthedRequest, res) => {
    const trust = await prisma.trust.findUnique({ where: { id: req.params.trustId } })
    if (!trust) throw new AppError(404, 'Trust not found')
    if (trust.joinCode.toLowerCase() !== req.body.code.toLowerCase()) throw new AppError(400, 'Invalid join code')
    const existing = await prisma.trustMember.findUnique({
      where: { trustId_userId: { trustId: trust.id, userId: req.user!.id } },
    })
    if (existing && existing.status !== 'REMOVED') throw new AppError(409, 'You are already a member of this trust')
    if (trust.joinMode === 'INVITE_ONLY') throw new AppError(403, 'This trust accepts members by invitation only')
    if (trust.joinMode === 'APPROVAL') {
      const joinRequest = await prisma.joinRequest.upsert({
        where: { trustId_userId: { trustId: trust.id, userId: req.user!.id } },
        create: { trustId: trust.id, userId: req.user!.id },
        update: { status: 'PENDING' },
      })
      ok(res, { message: 'Join request submitted for admin approval', status: 'PENDING_APPROVAL', joinRequest })
      return
    }
    const member = await prisma.trustMember.upsert({
      where: { trustId_userId: { trustId: trust.id, userId: req.user!.id } },
      create: { trustId: trust.id, userId: req.user!.id, role: 'MEMBER' },
      update: { status: 'ACTIVE' },
    })
    await audit({ actorId: req.user!.id, trustId: trust.id, action: 'MEMBER_ADDED', entityType: 'TrustMember', entityId: member.id })
    ok(res, { message: 'Joined successfully', member })
  })
)

router.get(
  '/:trustId/committee',
  asyncHandler(async (req: TrustContextRequest, res) => {
    const trust = await prisma.trust.findUnique({ where: { id: req.params.trustId } })
    if (!trust) throw new AppError(404, 'Trust not found')
    const showPublic = trust.showCommitteePublicly
    const committee = await prisma.trustMember.findMany({
      where: { trustId: trust.id, status: 'ACTIVE' },
      include: { user: true },
      orderBy: { joinedAt: 'asc' },
    })
    ok(res, committee.map((m) => ({ id: m.id, role: m.role, position: m.position, contactVisible: m.contactVisible, introduction: m.introduction, joinedAt: m.joinedAt, user: showPublic ? publicUser(m.user) : { id: m.user.id, name: m.user.name, profileImage: m.user.profileImage } })))
  })
)

router.patch(
  '/:trustId',
  requireAuth,
  loadTrustContext,
  requirePermission('trust:update'),
  validateBody(updateTrustSchema),
  asyncHandler(async (req: TrustContextRequest, res) => {
    const data = req.body
    const trust = await prisma.trust.update({
      where: { id: req.trustId },
      data: {
        ...(data.name !== undefined && { name: data.name }),
        ...(data.logoUrl !== undefined && { logoUrl: data.logoUrl }),
        ...(data.festivalTypes !== undefined && { festivalTypes: data.festivalTypes }),
        ...(data.description !== undefined && { description: data.description }),
        ...(data.registrationNumber !== undefined && { registrationNumber: data.registrationNumber }),
        ...(data.address !== undefined && { address: data.address }),
        ...(data.city !== undefined && { city: data.city }),
        ...(data.state !== undefined && { state: data.state }),
        ...(data.country !== undefined && { country: data.country }),
        ...(data.pinCode !== undefined && { pinCode: data.pinCode }),
        ...(data.contactPhone !== undefined && { contactPhone: data.contactPhone }),
        ...(data.contactEmail !== undefined && { contactEmail: data.contactEmail }),
        ...(data.website !== undefined && { website: data.website }),
        ...(data.upiId !== undefined && { upiId: data.upiId }),
        ...(data.financialYear !== undefined && { financialYear: data.financialYear }),
        ...(data.festivalStartDate !== undefined && { festivalStartDate: data.festivalStartDate ? new Date(data.festivalStartDate) : null }),
        ...(data.festivalEndDate !== undefined && { festivalEndDate: data.festivalEndDate ? new Date(data.festivalEndDate) : null }),
        ...(data.joinMode !== undefined && { joinMode: data.joinMode }),
      },
    })
    await audit({ actorId: req.user!.id, trustId: trust.id, action: 'TRUST_UPDATED', entityType: 'Trust', entityId: trust.id, metadata: { fields: Object.keys(data) } })
    ok(res, trust)
  })
)

export default router

import { Router } from 'express'
import { randomBytes } from 'node:crypto'
import { prisma } from '../../lib/prisma.js'
import { AppError, asyncHandler, ok } from '../../lib/http.js'
import { requireAuth } from '../../middleware/auth.js'
import { loadTrustContext, requirePermission, type TrustContextRequest } from '../../middleware/rbac.js'
import { validateBody, validateParams } from '../../middleware/validate.js'
import { addMemberSchema, updateMemberSchema, z } from '@pavati/shared'
import { config } from '../../config/index.js'
import { audit } from '../../services/audit.js'

const router = Router()
const paramsId = z.object({ trustId: z.string().uuid(), memberId: z.string().uuid() })

router.use('/:trustId/members', requireAuth, loadTrustContext)

router.get(
  '/:trustId/members',
  requirePermission('member:view'),
  asyncHandler(async (req: TrustContextRequest, res) => {
    const q = String(req.query.q ?? '').trim()
    const where: Record<string, unknown> = { trustId: req.trustId, status: { not: 'REMOVED' } }
    if (q) where.user = { name: { contains: q, mode: 'insensitive' } }
    const members = await prisma.trustMember.findMany({
      where,
      include: { user: true },
      orderBy: { joinedAt: 'asc' },
    })
    ok(res, members.map((m) => ({ id: m.id, trustId: m.trustId, userId: m.userId, role: m.role, permissions: m.permissions, status: m.status, position: m.position, contactVisible: m.contactVisible, introduction: m.introduction, joinedAt: m.joinedAt, user: m.user })))
  })
)

router.post(
  '/:trustId/members',
  requirePermission('member:add'),
  validateBody(addMemberSchema),
  asyncHandler(async (req: TrustContextRequest, res) => {
    const body = req.body
    let user = body.userId ? await prisma.user.findUnique({ where: { id: body.userId } }) : null
    if (!user && body.email) user = await prisma.user.findUnique({ where: { email: body.email } })
    if (!user && body.phone) user = await prisma.user.findUnique({ where: { phone: body.phone } })
    if (!user) {
      if (!body.name) throw new AppError(400, 'Provide a name to create a new member account')
      user = await prisma.user.create({
        data: {
          name: body.name,
          email: body.email ?? null,
          phone: body.phone ?? null,
          authProvider: body.email ? 'EMAIL' : 'PHONE',
        },
      })
    }
    const existing = await prisma.trustMember.findUnique({ where: { trustId_userId: { trustId: req.trustId!, userId: user.id } } })
    if (existing) {
      if (existing.status === 'REMOVED') {
        await prisma.trustMember.update({ where: { id: existing.id }, data: { status: 'ACTIVE', role: body.role } })
      } else {
        throw new AppError(409, 'User is already a member')
      }
    }
    const member = await prisma.trustMember.create({
      data: {
        trustId: req.trustId!,
        userId: user.id,
        role: body.role,
        position: body.position ?? null,
        introduction: body.introduction ?? null,
        contactVisible: body.contactVisible ?? false,
      },
    })
    await audit({ actorId: req.user!.id, trustId: req.trustId, action: 'MEMBER_ADDED', entityType: 'TrustMember', entityId: member.id, metadata: { role: body.role, userId: user.id } })
    ok(res, { member, user }, 201)
  })
)

router.patch(
  '/:trustId/members/:memberId',
  requirePermission('member:manage_roles'),
  validateParams(paramsId),
  validateBody(updateMemberSchema),
  asyncHandler(async (req: TrustContextRequest, res) => {
    const member = await prisma.trustMember.findUnique({ where: { id: req.params.memberId } })
    if (!member || member.trustId !== req.trustId) throw new AppError(404, 'Member not found')
    if (member.role === 'PRIMARY_ADMIN' && req.body.role && req.body.role !== 'PRIMARY_ADMIN') {
      throw new AppError(400, 'The Primary Admin role cannot be changed')
    }
    const updated = await prisma.trustMember.update({
      where: { id: member.id },
      data: {
        ...(req.body.role !== undefined && { role: req.body.role }),
        ...(req.body.position !== undefined && { position: req.body.position }),
        ...(req.body.introduction !== undefined && { introduction: req.body.introduction }),
        ...(req.body.contactVisible !== undefined && { contactVisible: req.body.contactVisible }),
        ...(req.body.permissions !== undefined && { permissions: req.body.permissions }),
      },
      include: { user: true },
    })
    await audit({ actorId: req.user!.id, trustId: req.trustId, action: 'MEMBER_ROLE_CHANGED', entityType: 'TrustMember', entityId: member.id, metadata: { to: req.body } })
    ok(res, updated)
  })
)

router.delete(
  '/:trustId/members/:memberId',
  requirePermission('member:remove'),
  validateParams(paramsId),
  asyncHandler(async (req: TrustContextRequest, res) => {
    const member = await prisma.trustMember.findUnique({ where: { id: req.params.memberId } })
    if (!member || member.trustId !== req.trustId) throw new AppError(404, 'Member not found')
    if (member.role === 'PRIMARY_ADMIN') throw new AppError(400, 'The Primary Admin cannot be removed')
    if (member.userId === req.user!.id) throw new AppError(400, 'You cannot remove yourself')
    await prisma.trustMember.update({ where: { id: member.id }, data: { status: 'REMOVED' } })
    await audit({ actorId: req.user!.id, trustId: req.trustId, action: 'MEMBER_REMOVED', entityType: 'TrustMember', entityId: member.id })
    ok(res, { message: 'Member removed' })
  })
)

router.post(
  '/:trustId/members/invite',
  requirePermission('member:invite'),
  validateBody(z.object({ email: z.string().email().optional(), phone: z.string().optional(), role: z.enum(['MEMBER', 'VOLUNTEER', 'COLLECTOR', 'COMMITTEE_MEMBER']).default('MEMBER') })),
  asyncHandler(async (req: TrustContextRequest, res) => {
    const token = randomBytes(12).toString('hex')
    await prisma.trustInvite.create({
      data: {
        trustId: req.trustId!,
        email: req.body.email ?? null,
        phone: req.body.phone ?? null,
        token,
        role: req.body.role,
        createdById: req.user!.id,
        expiresAt: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000),
      },
    })
    const inviteUrl = `${config.webOrigin}/join?invite=${token}`
    ok(res, { inviteUrl, token, message: 'Invitation created' }, 201)
  })
)

router.post(
  '/:trustId/join/invite',
  requireAuth,
  validateBody(z.object({ token: z.string().min(8) })),
  asyncHandler(async (req: TrustContextRequest, res) => {
    const invite = await prisma.trustInvite.findUnique({ where: { token: req.body.token } })
    if (!invite || invite.trustId !== req.params.trustId) throw new AppError(404, 'Invitation not found')
    if (invite.used || (invite.expiresAt && invite.expiresAt < new Date())) throw new AppError(400, 'Invitation expired or already used')
    await prisma.trustInvite.update({ where: { id: invite.id }, data: { used: true } })
    const member = await prisma.trustMember.upsert({
      where: { trustId_userId: { trustId: invite.trustId, userId: req.user!.id } },
      create: { trustId: invite.trustId, userId: req.user!.id, role: invite.role },
      update: { status: 'ACTIVE' },
    })
    await audit({ actorId: req.user!.id, trustId: invite.trustId, action: 'MEMBER_ADDED', entityType: 'TrustMember', entityId: member.id, metadata: { via: 'invite' } })
    ok(res, { message: 'Invitation accepted', member })
  })
)

router.get(
  '/:trustId/join-requests',
  requirePermission('member:view'),
  asyncHandler(async (req: TrustContextRequest, res) => {
    const requests = await prisma.joinRequest.findMany({
      where: { trustId: req.trustId, status: 'PENDING' },
      include: { trust: true },
      orderBy: { createdAt: 'asc' },
    })
    const userIds = requests.map((r) => r.userId)
    const users = await prisma.user.findMany({ where: { id: { in: userIds } } })
    ok(res, requests.map((r) => ({ id: r.id, userId: r.userId, message: r.message, createdAt: r.createdAt, user: users.find((u) => u.id === r.userId) })))
  })
)

router.post(
  '/:trustId/join-requests/:requestId',
  requirePermission('member:manage_roles'),
  validateParams(z.object({ trustId: z.string().uuid(), requestId: z.string().uuid() })),
  validateBody(z.object({ decision: z.enum(['APPROVE', 'REJECT']) })),
  asyncHandler(async (req: TrustContextRequest, res) => {
    const request = await prisma.joinRequest.findUnique({ where: { id: req.params.requestId } })
    if (!request || request.trustId !== req.trustId) throw new AppError(404, 'Join request not found')
    if (req.body.decision === 'APPROVE') {
      await prisma.joinRequest.update({ where: { id: request.id }, data: { status: 'APPROVED' } })
      const member = await prisma.trustMember.create({
        data: { trustId: req.trustId!, userId: request.userId, role: 'MEMBER' },
      })
      await audit({ actorId: req.user!.id, trustId: req.trustId, action: 'MEMBER_ADDED', entityType: 'TrustMember', entityId: member.id, metadata: { via: 'join_request' } })
      ok(res, { message: 'Approved', member })
    } else {
      await prisma.joinRequest.update({ where: { id: request.id }, data: { status: 'REJECTED' } })
      ok(res, { message: 'Rejected' })
    }
  })
)

export default router

import { Router } from 'express'
import { z } from '@pavati/shared'
import { prisma } from '../../lib/prisma.js'
import { AppError, asyncHandler, ok } from '../../lib/http.js'
import { requireAuth } from '../../middleware/auth.js'
import { loadTrustContext, requirePermission, type TrustContextRequest } from '../../middleware/rbac.js'
import { validateBody, validateQuery } from '../../middleware/validate.js'
import { createDonationSchema, createOnlineDonationSchema, mockPaymentCompleteSchema, PAYMENT_MODE } from '@pavati/shared'
import { paymentProvider } from '../../providers/payment.js'
import { generateReceipt } from '../../services/receipts.js'
import { sendReceiptNotifications } from '../../services/notifications.js'
import { audit } from '../../services/audit.js'

const router = Router()

router.use('/:trustId/donations', requireAuth, loadTrustContext)

const listQuery = z.object({
  from: z.string().optional(),
  to: z.string().optional(),
  paymentMode: z.enum(PAYMENT_MODE).optional(),
  category: z.string().optional(),
  collectorId: z.string().uuid().optional(),
  q: z.string().optional(),
  page: z.coerce.number().int().min(1).default(1),
  pageSize: z.coerce.number().int().min(1).max(100).default(20),
})

router.post(
  '/:trustId/donations',
  requirePermission('donation:create'),
  validateBody(createDonationSchema),
  asyncHandler(async (req: TrustContextRequest, res) => {
    const body = req.body
    const trust = await prisma.trust.findUnique({ where: { id: req.trustId! } })
    if (!trust) throw new AppError(404, 'Trust not found')

    const donation = await prisma.donation.create({
      data: {
        trustId: trust.id,
        donorName: body.donorName,
        phone: body.phone || null,
        address: body.address ?? null,
        amount: Math.round(body.amount),
        category: body.category,
        paymentMode: body.paymentMode,
        transactionRef: body.transactionRef ?? null,
        privacy: body.privacy,
        donationDate: body.paymentDate ? new Date(body.paymentDate) : new Date(),
        collectorId: req.trustMember!.id,
        status: 'SUCCEEDED',
        isOnline: false,
        notes: body.notes ?? null,
      },
    })

    const receipt = await generateReceipt({
      donationId: donation.id,
      trust,
      donation,
      collector: req.trustMember,
      actorId: req.user!.id,
    })

    await audit({ actorId: req.user!.id, trustId: trust.id, action: 'DONATION_CREATED', entityType: 'Donation', entityId: donation.id, metadata: { amount: donation.amount, mode: donation.paymentMode, receipt: receipt.receiptNumber } })

    await sendReceiptNotifications({
      trustId: trust.id,
      donorName: donation.donorName,
      donorPhone: donation.phone,
      donorEmail: null,
      amount: donation.amount,
      receiptNumber: receipt.receiptNumber,
      receiptVerificationToken: receipt.verificationToken,
      channels: { sms: trust.notificationSms, whatsapp: trust.notificationWhatsapp, email: trust.notificationEmail },
    })

    ok(res, { donation, receipt }, 201)
  })
)

router.get(
  '/:trustId/donations',
  requirePermission('donation:view'),
  validateQuery(listQuery),
  asyncHandler(async (req: TrustContextRequest, res) => {
    const q = req.query as z.infer<typeof listQuery>
    const where: Record<string, unknown> = { trustId: req.trustId }
    if (q.from || q.to) {
      where.donationDate = {}
      if (q.from) where.donationDate.gte = new Date(q.from)
      if (q.to) where.donationDate.lte = new Date(q.to)
    }
    if (q.paymentMode) where.paymentMode = q.paymentMode
    if (q.category) where.category = q.category
    if (q.collectorId) where.collectorId = q.collectorId
    if (q.q) where.donorName = { contains: q.q, mode: 'insensitive' }

    const page = q.page ?? 1
    const pageSize = q.pageSize ?? 20
    const [total, items] = await Promise.all([
      prisma.donation.count({ where }),
      prisma.donation.findMany({
        where,
        include: { receipts: { orderBy: { generatedAt: 'desc' }, take: 1 }, collector: { include: { user: true } }, campaign: true },
        orderBy: { donationDate: 'desc' },
        skip: (page - 1) * pageSize,
        take: pageSize,
      }),
    ])
    ok(res, { total, page, pageSize, items })
  })
)

router.get(
  '/:trustId/donations/:donationId',
  requirePermission('donation:view'),
  asyncHandler(async (req: TrustContextRequest, res) => {
    const donation = await prisma.donation.findFirst({
      where: { id: req.params.donationId, trustId: req.trustId },
      include: { receipts: true, collector: { include: { user: true } }, campaign: true },
    })
    if (!donation) throw new AppError(404, 'Donation not found')
    ok(res, donation)
  })
)

router.post(
  '/:trustId/donations/:donationId/void',
  requirePermission('donation:void'),
  validateBody(z.object({ reason: z.string().min(2).optional() })),
  asyncHandler(async (req: TrustContextRequest, res) => {
    const donation = await prisma.donation.findFirst({ where: { id: req.params.donationId, trustId: req.trustId } })
    if (!donation) throw new AppError(404, 'Donation not found')
    await prisma.$transaction([
      prisma.donation.update({ where: { id: donation.id }, data: { status: 'CANCELLED' } }),
      prisma.receipt.updateMany({ where: { donationId: donation.id }, data: { status: 'VOID' } }),
    ])
    await audit({ actorId: req.user!.id, trustId: req.trustId, action: 'DONATION_VOIDED', entityType: 'Donation', entityId: donation.id, metadata: { reason: req.body.reason ?? null } })
    ok(res, { message: 'Donation and receipts voided' })
  })
)

async function createPendingOnlineDonation(trustId: string, body: z.infer<typeof createOnlineDonationSchema>) {
  const trust = await prisma.trust.findUnique({ where: { id: trustId } })
  if (!trust) throw new AppError(404, 'Trust not found')
  if (body.anonymous && !trust.allowAnonymousDonations) throw new AppError(400, 'This trust does not allow anonymous donations')

  const donation = await prisma.donation.create({
    data: {
      trustId: trust.id,
      donorName: body.anonymous ? 'Anonymous Donor' : (body.donorName ?? 'Guest Donor'),
      phone: body.phone ?? null,
      email: body.email ?? null,
      amount: Math.round(body.amount),
      category: body.category,
      paymentMode: 'ONLINE',
      privacy: body.anonymous ? 'ANONYMOUS' : 'PRIVATE',
      status: 'PENDING',
      isOnline: true,
      campaignId: body.campaignId ?? null,
    },
  })
  const order = await paymentProvider.createOrder(donation.amount, donation.id)
  await prisma.paymentTransaction.create({
    data: { donationId: donation.id, provider: order.provider, orderId: order.orderId, amount: donation.amount, status: 'CREATED' },
  })
  return { trust, donation, order }
}

router.post(
  '/:trustId/payments/online',
  validateBody(createOnlineDonationSchema),
  asyncHandler(async (req: TrustContextRequest, res) => {
    const result = await createPendingOnlineDonation(req.params.trustId, req.body)
    ok(res, {
      trustId: result.trust.id,
      trustName: result.trust.name,
      trustLogo: result.trust.logoUrl,
      trustUpiId: result.trust.upiId,
      orderId: result.order.orderId,
      paymentId: `pay_${Date.now()}`,
      amount: result.donation.amount,
      donationId: result.donation.id,
      provider: result.order.provider,
    }, 201)
  })
)

router.post(
  '/payments/mock/complete',
  validateBody(mockPaymentCompleteSchema),
  asyncHandler(async (req, res) => {
    const { orderId, paymentId } = req.body
    const tx = await prisma.paymentTransaction.findUnique({ where: { orderId } })
    if (!tx) throw new AppError(404, 'Order not found')
    if (tx.status === 'SUCCEEDED') {
      const donation = await prisma.donation.findUnique({ where: { id: tx.donationId }, include: { trust: true, collector: true } })
      const receipt = await prisma.receipt.findFirst({ where: { donationId: tx.donationId } })
      return ok(res, { alreadyProcessed: true, donation, receipt })
    }
    const result = await prisma.$transaction(async (t) => {
      await t.paymentTransaction.update({ where: { id: tx.id }, data: { status: 'SUCCEEDED', paymentId, webhookVerified: true } })
      return t.donation.update({ where: { id: tx.donationId }, data: { status: 'SUCCEEDED' } })
    })
    const donation = await prisma.donation.findUnique({ where: { id: tx.donationId }, include: { trust: true } })
    const trust = donation!.trust
    const receipt = await generateReceipt({ donationId: donation!.id, trust, donation: donation! })
    await audit({ actorId: null, trustId: trust.id, action: 'DONATION_CREATED', entityType: 'Donation', entityId: donation!.id, metadata: { amount: donation!.amount, mode: 'ONLINE', orderId } })
    await sendReceiptNotifications({
      trustId: trust.id,
      donorName: donation!.donorName,
      donorPhone: donation!.phone,
      donorEmail: donation!.email,
      amount: donation!.amount,
      receiptNumber: receipt.receiptNumber,
      receiptVerificationToken: receipt.verificationToken,
      channels: { sms: trust.notificationSms, whatsapp: trust.notificationWhatsapp, email: trust.notificationEmail },
    })
    ok(res, { success: true, donation, receipt, verificationUrl: `/receipt/verify/${receipt.verificationToken}` })
  })
)

router.post(
  '/payments/webhook',
  asyncHandler(async (req, res) => {
    const signature = req.headers['x-razorpay-signature'] as string | undefined
    if (!signature) throw new AppError(400, 'Missing webhook signature')
    const event = req.body?.event
    const orderId = req.body?.payload?.order?.entity?.id as string | undefined
    if (!orderId) throw new AppError(400, 'Missing order id in payload')
    const tx = await prisma.paymentTransaction.findUnique({ where: { orderId } })
    if (!tx) throw new AppError(404, 'Order not found')
    await prisma.paymentTransaction.update({ where: { id: tx.id }, data: { status: event === 'payment.captured' ? 'SUCCEEDED' : 'FAILED', webhookVerified: true, providerResponse: req.body } })
    if (event === 'payment.captured') {
      await prisma.donation.update({ where: { id: tx.donationId }, data: { status: 'SUCCEEDED' } })
    }
    ok(res, { received: true })
  })
)

export default router

import { Router } from 'express'
import { prisma } from '../../lib/prisma.js'
import { AppError, asyncHandler, ok } from '../../lib/http.js'
import { requireAuth } from '../../middleware/auth.js'
import { loadTrustContext, requirePermission, type TrustContextRequest } from '../../middleware/rbac.js'
import { validateBody } from '../../middleware/validate.js'
import { createTemplateSchema, updateTemplateSchema } from '@pavati/shared'
import { audit } from '../../services/audit.js'

const router = Router()

router.use('/:trustId/templates', requireAuth, loadTrustContext)

router.get(
  '/:trustId/templates',
  requirePermission('template:manage'),
  asyncHandler(async (req: TrustContextRequest, res) => {
    const templates = await prisma.receiptTemplate.findMany({
      where: { trustId: req.trustId },
      orderBy: { createdAt: 'asc' },
    })
    ok(res, templates.map((t) => ({ ...t, fieldConfigs: t.fieldConfigs as unknown as unknown })))
  })
)

router.post(
  '/:trustId/templates',
  requirePermission('template:manage'),
  validateBody(createTemplateSchema),
  asyncHandler(async (req: TrustContextRequest, res) => {
    const body = req.body
    const count = await prisma.receiptTemplate.count({ where: { trustId: req.trustId } })
    const template = await prisma.receiptTemplate.create({
      data: {
        trustId: req.trustId!,
        name: body.name,
        pageSize: body.pageSize,
        widthMm: body.widthMm ?? null,
        heightMm: body.heightMm ?? null,
        backgroundImageUrl: body.backgroundImageUrl ?? null,
        fieldConfigs: body.fieldConfigs,
        active: count === 0,
      },
    })
    await audit({ actorId: req.user!.id, trustId: req.trustId, action: 'TEMPLATE_CREATED', entityType: 'ReceiptTemplate', entityId: template.id, metadata: { name: template.name } })
    ok(res, template, 201)
  })
)

router.get(
  '/:trustId/templates/:templateId',
  requirePermission('template:manage'),
  asyncHandler(async (req: TrustContextRequest, res) => {
    const template = await prisma.receiptTemplate.findFirst({ where: { id: req.params.templateId, trustId: req.trustId } })
    if (!template) throw new AppError(404, 'Template not found')
    ok(res, template)
  })
)

router.patch(
  '/:trustId/templates/:templateId',
  requirePermission('template:manage'),
  validateBody(updateTemplateSchema),
  asyncHandler(async (req: TrustContextRequest, res) => {
    const template = await prisma.receiptTemplate.findFirst({ where: { id: req.params.templateId, trustId: req.trustId } })
    if (!template) throw new AppError(404, 'Template not found')
    const body = req.body
    const updated = await prisma.receiptTemplate.update({
      where: { id: template.id },
      data: {
        ...(body.name !== undefined && { name: body.name }),
        ...(body.pageSize !== undefined && { pageSize: body.pageSize }),
        ...(body.widthMm !== undefined && { widthMm: body.widthMm }),
        ...(body.heightMm !== undefined && { heightMm: body.heightMm }),
        ...(body.backgroundImageUrl !== undefined && { backgroundImageUrl: body.backgroundImageUrl }),
        ...(body.fieldConfigs !== undefined && { fieldConfigs: body.fieldConfigs }),
      },
    })
    await audit({ actorId: req.user!.id, trustId: req.trustId, action: 'TEMPLATE_UPDATED', entityType: 'ReceiptTemplate', entityId: template.id })
    ok(res, updated)
  })
)

router.post(
  '/:trustId/templates/:templateId/activate',
  requirePermission('template:manage'),
  asyncHandler(async (req: TrustContextRequest, res) => {
    const template = await prisma.receiptTemplate.findFirst({ where: { id: req.params.templateId, trustId: req.trustId } })
    if (!template) throw new AppError(404, 'Template not found')
    await prisma.$transaction([
      prisma.receiptTemplate.updateMany({ where: { trustId: req.trustId }, data: { active: false } }),
      prisma.receiptTemplate.update({ where: { id: template.id }, data: { active: true } }),
    ])
    await audit({ actorId: req.user!.id, trustId: req.trustId, action: 'TEMPLATE_ACTIVATED', entityType: 'ReceiptTemplate', entityId: template.id })
    ok(res, { message: 'Template activated', templateId: template.id })
  })
)

router.delete(
  '/:trustId/templates/:templateId',
  requirePermission('template:manage'),
  asyncHandler(async (req: TrustContextRequest, res) => {
    const template = await prisma.receiptTemplate.findFirst({ where: { id: req.params.templateId, trustId: req.trustId } })
    if (!template) throw new AppError(404, 'Template not found')
    const inUse = await prisma.receipt.count({ where: { templateId: template.id } })
    if (inUse > 0) throw new AppError(400, 'Template is in use by receipts and cannot be deleted')
    await prisma.receiptTemplate.delete({ where: { id: template.id } })
    await audit({ actorId: req.user!.id, trustId: req.trustId, action: 'TEMPLATE_UPDATED', entityType: 'ReceiptTemplate', entityId: template.id, metadata: { deleted: true } })
    ok(res, { message: 'Template deleted' })
  })
)

export default router

import { Router } from 'express'
import { z } from '@pavati/shared'
import { prisma } from '../../lib/prisma.js'
import { AppError, asyncHandler, ok } from '../../lib/http.js'
import { requireAuth } from '../../middleware/auth.js'
import { loadTrustContext, requirePermission, type TrustContextRequest } from '../../middleware/rbac.js'
import { validateBody, validateQuery } from '../../middleware/validate.js'
import { generateReceipt, verifyReceiptData } from '../../services/receipts.js'
import { audit } from '../../services/audit.js'
import { fileFromUrl } from '../../providers/storage.js'
import { config } from '../../config/index.js'

const router = Router()

const listQuery = z.object({
  from: z.string().optional(),
  to: z.string().optional(),
  status: z.enum(['ACTIVE', 'VOID']).optional(),
  page: z.coerce.number().int().min(1).default(1),
  pageSize: z.coerce.number().int().min(1).max(100).default(20),
})

router.use('/:trustId/receipts', requireAuth, loadTrustContext)

router.get(
  '/:trustId/receipts',
  requirePermission('receipt:view'),
  validateQuery(listQuery),
  asyncHandler(async (req: TrustContextRequest, res) => {
    const q = req.query as z.infer<typeof listQuery>
    const where: Record<string, unknown> = { trustId: req.trustId }
    if (q.status) where.status = q.status
    if (q.from || q.to) {
      where.generatedAt = {}
      if (q.from) where.generatedAt.gte = new Date(q.from)
      if (q.to) where.generatedAt.lte = new Date(q.to)
    }
    const page = q.page ?? 1
    const pageSize = q.pageSize ?? 20
    const [total, items] = await Promise.all([
      prisma.receipt.count({ where }),
      prisma.receipt.findMany({
        where,
        include: { donation: true, template: { select: { name: true } } },
        orderBy: { generatedAt: 'desc' },
        skip: (page - 1) * pageSize,
        take: pageSize,
      }),
    ])
    ok(res, { total, page, pageSize, items })
  })
)

router.post(
  '/:trustId/receipts',
  requirePermission('receipt:create'),
  validateBody(z.object({ donationId: z.string().uuid(), templateId: z.string().uuid().optional(), reason: z.string().optional() })),
  asyncHandler(async (req: TrustContextRequest, res) => {
    const donation = await prisma.donation.findFirst({ where: { id: req.body.donationId, trustId: req.trustId } })
    if (!donation) throw new AppError(404, 'Donation not found')
    const trust = await prisma.trust.findUnique({ where: { id: req.trustId } })
    if (!trust) throw new AppError(404, 'Trust not found')
    const collector = await prisma.trustMember.findUnique({ where: { id: donation.collectorId ?? '' }, include: { user: true } })
    const receipt = await generateReceipt({ donationId: donation.id, trust, donation, collector, actorId: req.user!.id, templateId: req.body.templateId })
    await audit({ actorId: req.user!.id, trustId: req.trustId, action: 'RECEIPT_CREATED', entityType: 'Receipt', entityId: receipt.id, metadata: { reason: req.body.reason ?? 'reprint' } })
    ok(res, receipt, 201)
  })
)

router.post(
  '/:trustId/receipts/:receiptId/void',
  requirePermission('receipt:void'),
  validateBody(z.object({ reason: z.string().min(2) })),
  asyncHandler(async (req: TrustContextRequest, res) => {
    const receipt = await prisma.receipt.findFirst({ where: { id: req.params.receiptId, trustId: req.trustId } })
    if (!receipt) throw new AppError(404, 'Receipt not found')
    await prisma.receipt.update({
      where: { id: receipt.id },
      data: { status: 'VOID', voidedById: req.user!.id, voidReason: req.body.reason },
    })
    await audit({ actorId: req.user!.id, trustId: req.trustId, action: 'RECEIPT_VOIDED', entityType: 'Receipt', entityId: receipt.id, metadata: { reason: req.body.reason } })
    ok(res, { message: 'Receipt voided' })
  })
)

router.get(
  '/receipts/:receiptId/pdf',
  requireAuth,
  asyncHandler(async (req, res) => {
    const receipt = await prisma.receipt.findUnique({ where: { id: req.params.receiptId } })
    if (!receipt || receipt.status !== 'ACTIVE') throw new AppError(404, 'Receipt not found')
    const member = await prisma.trustMember.findUnique({
      where: { trustId_userId: { trustId: receipt.trustId, userId: req.user!.id } },
    })
    const isTrustMember = member && member.status === 'ACTIVE'
    const isDonor = await prisma.donation.findFirst({ where: { id: receipt.donationId, phone: req.user!.phone ?? undefined } })
    if (!isTrustMember && !isDonor) throw new AppError(403, 'Not authorized to view this receipt')
    if (!receipt.pdfUrl) throw new AppError(404, 'PDF not generated')
    const file = fileFromUrl(receipt.pdfUrl)
    if (!file) throw new AppError(404, 'PDF file missing')
    res.setHeader('Content-Type', 'application/pdf')
    res.setHeader('Content-Disposition', `attachment; filename="${receipt.receiptNumber}.pdf"`)
    res.send(file.buffer)
  })
)

router.get(
  '/receipt/verify/:token',
  asyncHandler(async (req, res) => {
    const data = await verifyReceiptData(req.params.token)
    if (!data) throw new AppError(404, 'Receipt not found or invalid verification link')
    ok(res, data)
  })
)

export default router

import { Router } from 'express'
import { z, slugify, randomCode } from '@pavati/shared'
import { prisma } from '../../lib/prisma.js'
import { AppError, asyncHandler, ok } from '../../lib/http.js'
import { requireAuth } from '../../middleware/auth.js'
import { loadTrustContext, requirePermission, type TrustContextRequest } from '../../middleware/rbac.js'
import { validateBody } from '../../middleware/validate.js'
import { createCampaignSchema } from '@pavati/shared'
import { config } from '../../config/index.js'
import { audit } from '../../services/audit.js'

const router = Router()

router.use('/:trustId/campaigns', requireAuth, loadTrustContext)

router.get(
  '/:trustId/campaigns',
  requirePermission('campaign:view'),
  asyncHandler(async (req: TrustContextRequest, res) => {
    const campaigns = await prisma.paymentCampaign.findMany({
      where: { trustId: req.trustId },
      include: { _count: { select: { donations: true } } },
      orderBy: { createdAt: 'desc' },
    })
    ok(res, campaigns.map((c) => ({ ...c, donationCount: c._count.donations, paymentUrl: `${config.publicBaseUrl}/donate/${c.slug}` })))
  })
)

router.post(
  '/:trustId/campaigns',
  requirePermission('campaign:manage'),
  validateBody(createCampaignSchema),
  asyncHandler(async (req: TrustContextRequest, res) => {
    const body = req.body
    let slug = slugify(body.name)
    const existing = await prisma.paymentCampaign.findUnique({ where: { slug } })
    if (existing) slug = `${slug}-${randomCode(4).toLowerCase()}`
    const campaign = await prisma.paymentCampaign.create({
      data: {
        trustId: req.trustId!,
        name: body.name,
        description: body.description ?? null,
        slug,
        category: body.category ?? null,
        suggestedAmounts: body.suggestedAmounts ?? [],
      },
    })
    await audit({ actorId: req.user!.id, trustId: req.trustId, action: 'CAMPAIGN_CREATED', entityType: 'PaymentCampaign', entityId: campaign.id, metadata: { slug } })
    ok(res, { ...campaign, paymentUrl: `${config.publicBaseUrl}/donate/${slug}` }, 201)
  })
)

router.patch(
  '/:trustId/campaigns/:campaignId',
  requirePermission('campaign:manage'),
  validateBody(createCampaignSchema.partial()),
  asyncHandler(async (req: TrustContextRequest, res) => {
    const campaign = await prisma.paymentCampaign.findFirst({ where: { id: req.params.campaignId, trustId: req.trustId } })
    if (!campaign) throw new AppError(404, 'Campaign not found')
    const body = req.body
    const updated = await prisma.paymentCampaign.update({
      where: { id: campaign.id },
      data: {
        ...(body.name !== undefined && { name: body.name }),
        ...(body.description !== undefined && { description: body.description }),
        ...(body.category !== undefined && { category: body.category }),
        ...(body.suggestedAmounts !== undefined && { suggestedAmounts: body.suggestedAmounts }),
      },
    })
    await audit({ actorId: req.user!.id, trustId: req.trustId, action: 'CAMPAIGN_UPDATED', entityType: 'PaymentCampaign', entityId: campaign.id })
    ok(res, updated)
  })
)

router.post(
  '/:trustId/campaigns/:campaignId/toggle',
  requirePermission('campaign:manage'),
  asyncHandler(async (req: TrustContextRequest, res) => {
    const campaign = await prisma.paymentCampaign.findFirst({ where: { id: req.params.campaignId, trustId: req.trustId } })
    if (!campaign) throw new AppError(404, 'Campaign not found')
    const updated = await prisma.paymentCampaign.update({ where: { id: campaign.id }, data: { active: !campaign.active } })
    await audit({ actorId: req.user!.id, trustId: req.trustId, action: 'CAMPAIGN_TOGGLED', entityType: 'PaymentCampaign', entityId: campaign.id, metadata: { active: updated.active } })
    ok(res, updated)
  })
)

router.delete(
  '/:trustId/campaigns/:campaignId',
  requirePermission('campaign:manage'),
  asyncHandler(async (req: TrustContextRequest, res) => {
    const campaign = await prisma.paymentCampaign.findFirst({ where: { id: req.params.campaignId, trustId: req.trustId } })
    if (!campaign) throw new AppError(404, 'Campaign not found')
    await prisma.paymentCampaign.delete({ where: { id: campaign.id } })
    await audit({ actorId: req.user!.id, trustId: req.trustId, action: 'CAMPAIGN_UPDATED', entityType: 'PaymentCampaign', entityId: campaign.id, metadata: { deleted: true } })
    ok(res, { message: 'Campaign deleted' })
  })
)

router.get(
  '/public/campaigns/:slug',
  asyncHandler(async (req, res) => {
    const campaign = await prisma.paymentCampaign.findUnique({
      where: { slug: req.params.slug },
      include: { trust: true },
    })
    if (!campaign || !campaign.active) throw new AppError(404, 'Campaign not found')
    ok(res, {
      campaign: { id: campaign.id, name: campaign.name, description: campaign.description, category: campaign.category, suggestedAmounts: campaign.suggestedAmounts },
      trust: { id: campaign.trust.id, name: campaign.trust.name, logoUrl: campaign.trust.logoUrl, description: campaign.trust.description, city: campaign.trust.city, upiId: campaign.trust.upiId, festivalTypes: campaign.trust.festivalTypes, allowAnonymousDonations: campaign.trust.allowAnonymousDonations },
    })
  })
)

export default router

