import { useState } from 'react'
import { Link, useNavigate, useLocation } from 'react-router-dom'
import { useForm } from 'react-hook-form'
import { z } from 'zod'
import { zodResolver } from '@hookform/resolvers/zod'
import { toast } from 'sonner'
import { ArrowLeft } from 'lucide-react'
import { api, setTokens, getAccessToken } from '../../lib/api'
import { useAuth } from '../../lib/stores/auth'
import { Input, Button, Card } from '../../components/ui'

const schema = z.object({
  identifier: z.string().min(3, 'Enter your phone or email'),
  password: z.string().min(6, 'Password must be at least 6 characters'),
})

type Form = z.infer<typeof schema>

export default function LoginPage() {
  const navigate = useNavigate()
  const location = useLocation()
  const [loading, setLoading] = useState(false)
  const { register, handleSubmit, formState: { errors } } = useForm<Form>({ resolver: zodResolver(schema) })

  const onSubmit = async (data: Form) => {
    setLoading(true)
    try {
      const res = await api.post<{ accessToken: string; refreshToken: string; pendingOtp?: boolean; identifier?: string }>('/auth/login', data)
      if (res.pendingOtp) {
        navigate('/otp', { state: { identifier: res.identifier } })
        return
      }
      setTokens(res.accessToken, res.refreshToken)
      const me = await api.get<{ user: any; memberships: any[] }>('/auth/me')
      useAuth.getState().setSession(me)
      toast.success('Welcome back!')
      navigate((location.state as any)?.from ?? '/app')
    } catch (e: any) {
      toast.error(e.message)
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="flex min-h-screen items-center justify-center bg-gradient-to-br from-cream-50 via-saffron-50 to-maroon-700/10 p-4">
