          <h1 className="mt-4 text-2xl font-bold text-stone-900">Welcome back</h1>
          <p className="mt-1 text-sm text-stone-500">Log in to your Pāvati Pustak account</p>
        </div>
        <Card className="p-6">
          <form onSubmit={handleSubmit(onSubmit)} className="space-y-4">
            <div>
              <label className="label">Phone or email</label>
              <Input placeholder="9876543210 or you@example.com" {...register('identifier')} autoFocus />
              {errors.identifier && <p className="mt-1 text-xs text-red-600">{errors.identifier.message}</p>}
            </div>
            <div>
              <label className="label">Password</label>
              <Input type="password" placeholder="••••••••" {...register('password')} />
