import { useEffect, useRef, useState } from 'react'
import { useLocation, useNavigate } from 'react-router-dom'
import { toast } from 'sonner'
import { api, setTokens } from '../../lib/api'
import { useAuth } from '../../lib/stores/auth'
import { Button, Card } from '../../components/ui'

export default function OtpPage() {
  const location = useLocation()
  const navigate = useNavigate()
  const identifier = (location.state as any)?.identifier
  const [digits, setDigits] = useState<string[]>(Array(6).fill(''))
  const [loading, setLoading] = useState(false)
  const [resending, setResending] = useState(false)
  const [countdown, setCountdown] = useState(30)
  const inputs = useRef<(HTMLInputElement | null)[]>([])

  useEffect(() => {
    if (countdown <= 0) return
    const t = setInterval(() => setCountdown((c) => c - 1), 1000)
    return () => clearInterval(t)
  }, [countdown])

  const setDigit = (i: number, v: string) => {
    const next = [...digits]
    next[i] = v.replace(/\D/g, '').slice(-1)
    setDigits(next)
    if (v && i < 5) inputs.current[i + 1]?.focus()
  }

  const onKey = (i: number, e: React.KeyboardEvent) => {
    if (e.key === 'Backspace' && !digits[i] && i > 0) inputs.current[i - 1]?.focus()
  }

  const submit = async () => {
    const otp = digits.join('')
    if (otp.length < 6) return toast.error('Enter the 6-digit code')
    setLoading(true)
    try {
      const res = await api.post<{ accessToken: string; refreshToken: string }>('/auth/verify-otp', {
        identifier,
        otp,
        purpose: 'login',
      })
      setTokens(res.accessToken, res.refreshToken)
      const me = await api.get<{ user: any; memberships: any[] }>('/auth/me')
      useAuth.getState().setSession(me)
      toast.success('Verified!')
      navigate('/app')
    } catch (e: any) {
      toast.error(e.message)
    } finally {
      setLoading(false)
    }
  }

  const resend = async () => {
    setResending(true)
    try {
      await api.post('/auth/request-otp', { identifier })
      toast.success('OTP sent', { description: 'Mock mode: check the server console / dev-otp.' })
      setCountdown(30)
    } catch (e: any) {
      toast.error(e.message)
    } finally {
      setResending(false)
    }
  }

  return (
    <div className="flex min-h-screen items-center justify-center bg-gradient-to-br from-cream-50 via-saffron-50 to-maroon-700/10 p-4">
      <div className="w-full max-w-sm animate-slide-up">
        <div className="mb-6 text-center">
          <div className="mx-auto flex h-14 w-14 items-center justify-center rounded-2xl bg-maroon-700 text-2xl text-white">🔐</div>
          <h1 className="mt-4 text-2xl font-bold text-stone-900">Verify your identity</h1>
          <p className="mt-1 text-sm text-stone-500">
            Enter the 6-digit code sent to <span className="font-medium">{identifier}</span>
          </p>
        </div>
        <Card className="p-6">
          <div className="flex justify-between gap-2">
            {digits.map((d, i) => (
              <input
                key={i}
                ref={(el) => { inputs.current[i] = el }}
                value={d}
                onChange={(e) => setDigit(i, e.target.value)}
                onKeyDown={(e) => onKey(i, e)}
                inputMode="numeric"
                maxLength={1}
                className="h-12 w-full rounded-xl border border-stone-300 text-center text-xl font-bold focus:border-saffron-500 focus:outline-none focus:ring-2 focus:ring-saffron-100"
              />
            ))}
          </div>
          <Button className="mt-5 w-full" onClick={submit} loading={loading}>Verify & continue</Button>
          <div className="mt-4 text-center">
            {countdown > 0 ? (
              <p className="text-xs text-stone-400">Resend code in {countdown}s</p>
            ) : (
              <button onClick={resend} disabled={resending} className="text-xs font-semibold text-saffron-600 hover:underline">
                {resending ? 'Sending…' : 'Resend code'}
              </button>
            )}
          </div>
        </Card>
        <p className="mt-4 text-center text-xs text-stone-400">Mock OTP provider — the code is printed in the API logs as <b>devOtp</b>.</p>
      </div>
    </div>
  )
}

