import { useEffect, useState } from 'react'
import { useNavigate, useParams, useSearchParams } from 'react-router-dom'
import { toast } from 'sonner'
import { QRCodeSVG } from 'qrcode.react'
import { SUGGESTED_AMOUNTS, DONATION_CATEGORIES } from '@pavati/shared'
import { api } from '../../lib/api'
import { Button, Card, Input, Select, Spinner } from '../../components/ui'
import { formatINR } from '../../lib/utils'

interface PublicCampaign {
  campaign: { id: string; name: string; description: string | null; category: string | null; suggestedAmounts: number[] }
  trust: { id: string; name: string; logoUrl: string | null; description: string | null; city: string | null; upiId: string | null; festivalTypes: string[]; allowAnonymousDonations: boolean }
}

export default function DonatePage() {
  const { slug } = useParams()
  const [params] = useSearchParams()
  const trustParam = params.get('trust')
  const navigate = useNavigate()
  const [data, setData] = useState<PublicCampaign | null>(null)
  const [trust, setTrust] = useState<any>(null)
  const [loading, setLoading] = useState(true)
  const [amount, setAmount] = useState<number>(501)
  const [customAmount, setCustomAmount] = useState('')
  const [donorName, setDonorName] = useState('')
  const [phone, setPhone] = useState('')
  const [email, setEmail] = useState('')
  const [category, setCategory] = useState('General Donation')
  const [anonymous, setAnonymous] = useState(false)
  const [submitting, setSubmitting] = useState(false)

  useEffect(() => {
    if (slug) {
      api.get<PublicCampaign>(`/campaigns/public/campaigns/${slug}`).then((d) => {
        setData(d)
        setCategory(d.campaign.category ?? 'General Donation')
        if (d.campaign.suggestedAmounts?.length) setAmount(d.campaign.suggestedAmounts[0])
      }).finally(() => setLoading(false))
    } else if (trustParam) {
      api.get<any>(`/trusts/${trustParam}`).then((t) => {
        setTrust(t)
        setData({ campaign: { id: '', name: `Donation to ${t.name}`, description: null, category: null, suggestedAmounts: [] }, trust: t })
      }).finally(() => setLoading(false))
    } else {
      setLoading(false)
    }
  }, [slug, trustParam])

  if (loading) return <div className="p-10"><Spinner /></div>
  if (!data) return <div className="p-10 text-center text-stone-500">Donation page not found</div>

  const effectiveAmount = customAmount ? Number(customAmount) : amount
  const suggested = data.campaign.suggestedAmounts?.length ? data.campaign.suggestedAmounts : SUGGESTED_AMOUNTS

  const submit = async () => {
    if (!effectiveAmount || effectiveAmount <= 0) return toast.error('Enter a valid amount')
    if (!anonymous && !donorName) return toast.error('Enter your name (or choose anonymous)')
    setSubmitting(true)
    try {
      const res = await api.post<{ orderId: string; paymentId: string; donationId: string; trustId: string }>(
        `/trusts/${data.trust.id}/payments/online`,
        {
          trustId: data.trust.id,
          campaignId: data.campaign.id || undefined,
          donorName: donorName || undefined,
          phone: phone || undefined,
          email: email || undefined,
          amount: effectiveAmount,
          category,
          anonymous,
        }
      )
      await api.post('/payments/mock/complete', { orderId: res.orderId, paymentId: res.paymentId })
      navigate(`/payment-success?orderId=${res.orderId}&donationId=${res.donationId}`)
    } catch (e: any) {
      toast.error(e.message)
    } finally {
      setSubmitting(false)
    }
  }

  const donateUrl = window.location.href

  return (
    <div className="min-h-screen bg-gradient-to-br from-cream-50 via-saffron-50 to-maroon-700/10">
      <div className="mx-auto grid max-w-5xl gap-6 px-4 py-10 sm:px-6 lg:grid-cols-5">
        <div className="lg:col-span-3">
          <div className="flex items-center gap-3">
            <div className="flex h-14 w-14 items-center justify-center overflow-hidden rounded-2xl bg-white text-xl font-bold text-saffron-700 shadow-sm">
              {data.trust.logoUrl ? <img src={data.trust.logoUrl} alt="" className="h-full w-full object-cover" /> : data.trust.name[0]}
            </div>
            <div>
              <h1 className="text-2xl font-extrabold text-stone-900">{data.campaign.name}</h1>
              <p className="text-sm text-stone-500">{data.trust.name} · {data.trust.city ?? ''}</p>
            </div>
          </div>
          {data.trust.description && <p className="mt-4 text-sm text-stone-600">{data.trust.description}</p>}
          {data.campaign.description && <p className="mt-2 text-sm text-stone-500">{data.campaign.description}</p>}

          <Card className="mt-6 p-6">
            <h2 className="font-bold text-stone-900">Choose an amount</h2>
            <div className="mt-3 grid grid-cols-3 gap-2 sm:grid-cols-6">
              {suggested.map((a) => (
                <button
                  key={a}
                  onClick={() => { setAmount(a); setCustomAmount('') }}
                  className={`rounded-xl border px-2 py-2.5 text-sm font-semibold transition-colors ${!customAmount && amount === a ? 'border-saffron-500 bg-saffron-50 text-saffron-700' : 'border-stone-200 bg-white text-stone-700 hover:border-saffron-300'}`}
                >
                  ₹{a}
                </button>
              ))}
            </div>
            <div className="mt-3">
              <label className="label">Or enter custom amount</label>
              <Input type="number" min={1} placeholder="₹" value={customAmount} onChange={(e) => setCustomAmount(e.target.value)} />
            </div>

            <div className="mt-5 grid gap-4 sm:grid-cols-2">
              <div>
                <label className="label">Your name</label>
                <Input placeholder="Full name" value={donorName} onChange={(e) => setDonorName(e.target.value)} disabled={anonymous} />
              </div>
              <div>
                <label className="label">Phone <span className="text-stone-400">(for receipt)</span></label>
                <Input placeholder="9876543210" inputMode="numeric" value={phone} onChange={(e) => setPhone(e.target.value.replace(/\D/g, '').slice(0, 10))} />
              </div>
              <div>
                <label className="label">Email <span className="text-stone-400">(optional)</span></label>
                <Input type="email" placeholder="you@example.com" value={email} onChange={(e) => setEmail(e.target.value)} />
              </div>
              <div>
                <label className="label">Category</label>
                <Select value={category} onChange={(e) => setCategory(e.target.value)}>
                  {DONATION_CATEGORIES.map((c) => <option key={c} value={c}>{c}</option>)}
                </Select>
              </div>
            </div>

            {data.trust.allowAnonymousDonations && (
              <label className="mt-4 flex items-center gap-2 text-sm text-stone-600">
                <input type="checkbox" checked={anonymous} onChange={(e) => setAnonymous(e.target.checked)} className="h-4 w-4 rounded border-stone-300 text-saffron-600 focus:ring-saffron-500" />
                Donate anonymously
              </label>
            )}

            <Button className="mt-6 w-full py-3.5 text-base" onClick={submit} loading={submitting}>
              Donate {effectiveAmount > 0 ? formatINR(effectiveAmount) : ''}
            </Button>
            <p className="mt-2 text-center text-xs text-stone-400">
              Secure mock payment · You'll receive a digital Pāvati receipt instantly
            </p>
          </Card>
        </div>

        <div className="lg:col-span-2">
          <Card className="p-6 text-center">
            <h3 className="font-semibold text-stone-900">Scan to donate</h3>
            <div className="mx-auto mt-4 w-fit rounded-2xl border border-stone-200 bg-white p-4">
              <QRCodeSVG value={donateUrl} size={180} fgColor="#7f1d1d" />
            </div>
            <p className="mt-3 text-xs text-stone-500">Point your phone camera at the QR code</p>
            {data.trust.upiId && (
              <div className="mt-4 rounded-xl bg-stone-50 p-3">
                <p className="text-xs text-stone-400">Or pay directly via UPI</p>
                <p className="font-mono text-sm font-semibold text-stone-700">{data.trust.upiId}</p>
              </div>
            )}
            <button
              onClick={() => { navigator.clipboard.writeText(donateUrl); toast.success('Link copied!') }}
              className="mt-4 text-xs font-semibold text-saffron-600 hover:underline"
            >
              Copy donation link
            </button>
          </Card>
        </div>
      </div>
    </div>
  )
}

import { useEffect, useState } from 'react'
import { Link, useSearchParams } from 'react-router-dom'
import { CheckCircle2, Download, ArrowLeft } from 'lucide-react'
import { api } from '../../lib/api'
import { Button, Card, Spinner } from '../../components/ui'
import { formatINR } from '../../lib/utils'

export default function PaymentSuccessPage() {
  const [params] = useSearchParams()
  const [donation, setDonation] = useState<any>(null)
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    const orderId = params.get('orderId')
    if (!orderId) return setLoading(false)
    api.get(`/trusts/${params.get('donationId') ?? ''}/donations/${params.get('donationId') ?? ''}`).catch(() => null)
    api.post<{ alreadyProcessed?: boolean; donation: any; receipt: any; verificationUrl?: string }>('/payments/mock/complete', {
      orderId,
      paymentId: `pay_${Date.now()}`,
    }).then((res) => {
      setDonation(res.donation)
      sessionStorage.setItem('pp_last_receipt', JSON.stringify({ donation: res.donation, receipt: res.receipt, verificationUrl: res.verificationUrl }))
    }).finally(() => setLoading(false))
  }, [params])

  const saved = donation ? { donation, receipt: donation.receipts?.[0], verificationUrl: null } : JSON.parse(sessionStorage.getItem('pp_last_receipt') ?? 'null')

  if (loading) return <div className="p-10"><Spinner /></div>

  const d = donation ?? saved?.donation
  const receipt = donation?.receipts?.[0] ?? saved?.receipt

  return (
    <div className="flex min-h-screen items-center justify-center bg-gradient-to-br from-emerald-50 via-cream-50 to-saffron-50 p-4">
      <div className="w-full max-w-md animate-slide-up">
        <Card className="overflow-hidden">
          <div className="bg-emerald-500 p-8 text-center text-white">
            <div className="mx-auto flex h-16 w-16 items-center justify-center rounded-full bg-white/20"><CheckCircle2 className="h-10 w-10" /></div>
            <h1 className="mt-4 text-2xl font-extrabold">Donation successful!</h1>
            <p className="mt-1 text-sm text-white/80">धन्यवाद - Thank you for your generous support</p>
          </div>
          <div className="p-6">
            {d && (
              <div className="space-y-2 rounded-2xl bg-stone-50 p-4 text-sm">
                <div className="flex justify-between"><span className="text-stone-500">Amount</span><span className="font-bold text-maroon-700">{formatINR(d.amount)}</span></div>
                <div className="flex justify-between"><span className="text-stone-500">Category</span><span>{d.category}</span></div>
                <div className="flex justify-between"><span className="text-stone-500">Donor</span><span>{d.donorName}</span></div>
                {receipt && <div className="flex justify-between"><span className="text-stone-500">Receipt No</span><span className="font-mono font-semibold">{receipt.receiptNumber}</span></div>}
              </div>
            )}
            <div className="mt-5 space-y-2">
              {receipt && (
                <a href={`/api/v1/receipts/receipts/${receipt.id}/pdf`} target="_blank" rel="noreferrer" className="btn-primary w-full">
                  <Download className="h-4 w-4" /> Download Pāvati (PDF)
                </a>
              )}
              {saved?.verificationUrl && (
                <Link to={saved.verificationUrl} className="btn-outline w-full">Verify receipt</Link>
              )}
              <Link to="/" className="btn-ghost w-full">
                <ArrowLeft className="h-4 w-4" /> Back to home
              </Link>
            </div>
          </div>
        </Card>
      </div>
    </div>
  )
}

import { useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { useForm } from 'react-hook-form'
import { z } from 'zod'
import { zodResolver } from '@hookform/resolvers/zod'
import { toast } from 'sonner'
import { Upload, UserCircle2, LogOut, KeyRound, Heart } from 'lucide-react'
import { api, uploadFile, clearTokens } from '../../lib/api'
import { useAuth } from '../../lib/stores/auth'
import { Button, Card, CardHeader, Input, PageHeader, Badge } from '../../components/ui'
import { fileToDataUrl, formatDate } from '../../lib/utils'
import { ROLE_LABELS } from '@pavati/shared'

const profileSchema = z.object({
  name: z.string().min(2),
  email: z.string().email().optional().or(z.literal('')),
  phone: z.string().regex(/^[6-9]\d{9}$/).optional().or(z.literal('')),
})
const passSchema = z.object({
  currentPassword: z.string().min(1),
  newPassword: z.string().min(6),
})

export default function AccountPage() {
  const navigate = useNavigate()
  const user = useAuth((s) => s.user)
  const memberships = useAuth((s) => s.memberships)
  const updateUser = useAuth((s) => s.updateUser)
  const [saving, setSaving] = useState(false)
  const [changing, setChanging] = useState(false)
  const [donations, setDonations] = useState<any[]>([])
  const [loaded, setLoaded] = useState(false)

  const profile = useForm<z.infer<typeof profileSchema>>({ resolver: zodResolver(profileSchema), defaultValues: { name: user?.name ?? '', email: user?.email ?? '', phone: user?.phone ?? '' } })
  const pass = useForm<z.infer<typeof passSchema>>({ resolver: zodResolver(passSchema) })

  const onPhoto = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (!file) return
    const dataUrl = await fileToDataUrl(file)
    const res = await uploadFile(dataUrl)
    const updated = await api.patch<any>('/users/me', { profileImage: res.url })
    updateUser(updated)
    toast.success('Photo updated')
  }

  const onProfile = async (d: any) => {
    setSaving(true)
    try {
      const updated = await api.patch<any>('/users/me', d)
      updateUser(updated)
      toast.success('Profile updated')
    } catch (e: any) {
      toast.error(e.message)
    } finally {
      setSaving(false)
    }
  }

  const onChangePass = async (d: any) => {
    setChanging(true)
    try {
      await api.post('/users/me/change-password', d)
      toast.success('Password changed')
      pass.reset()
    } catch (e: any) {
      toast.error(e.message)
    } finally {
      setChanging(false)
    }
  }

  const loadDonations = async () => {
    const res = await api.get<any[]>('/users/me/donations')
    setDonations(res)
    setLoaded(true)
  }

  const logout = () => {
    const rt = localStorage.getItem('pp_refresh')
    if (rt) fetch('/api/v1/auth/logout', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ refreshToken: rt }) }).catch(() => {})
    clearTokens()
    useAuth.getState().logout()
    navigate('/login')
  }

  return (
    <div className="min-h-screen bg-cream-50">
      <div className="mx-auto max-w-3xl px-4 py-8 sm:px-6">
        <PageHeader title="My account" subtitle="Profile, memberships and your donations" />

        <Card>
          <CardHeader title="Profile" />
          <div className="p-6">
            <div className="flex items-center gap-4">
              <div className="relative">
                <div className="flex h-16 w-16 items-center justify-center overflow-hidden rounded-2xl bg-saffron-100 text-2xl font-bold text-saffron-700">
                  {user?.profileImage ? <img src={user.profileImage} alt="" className="h-full w-full object-cover" /> : <UserCircle2 className="h-8 w-8" />}
                </div>
                <label className="absolute -bottom-1 -right-1 cursor-pointer rounded-full bg-saffron-600 p-1.5 text-white shadow">
                  <Upload className="h-3.5 w-3.5" />
                  <input type="file" accept="image/*" className="hidden" onChange={onPhoto} />
                </label>
              </div>
              <div>
                <p className="font-semibold text-stone-900">{user?.name}</p>
                <Badge color="saffron">{user?.authProvider}</Badge>
              </div>
            </div>
            <form onSubmit={profile.handleSubmit(onProfile)} className="mt-5 grid gap-4 sm:grid-cols-2">
              <div><label className="label">Name</label><Input {...profile.register('name')} /></div>
              <div><label className="label">Email</label><Input {...profile.register('email')} /></div>
              <div><label className="label">Phone</label><Input {...profile.register('phone')} inputMode="numeric" /></div>
              <div className="flex items-end"><Button type="submit" loading={saving}>Save profile</Button></div>
            </form>
          </div>
        </Card>

        <Card className="mt-5">
          <CardHeader title="Change password" />
          <div className="p-6">
            <form onSubmit={pass.handleSubmit(onChangePass)} className="grid gap-4 sm:grid-cols-3">
              <div><label className="label">Current password</label><Input type="password" {...pass.register('currentPassword')} /></div>
              <div><label className="label">New password</label><Input type="password" {...pass.register('newPassword')} /></div>
              <div className="flex items-end"><Button variant="outline" type="submit" loading={changing}><KeyRound className="h-4 w-4" /> Update</Button></div>
            </form>
          </div>
        </Card>

        <Card className="mt-5">
          <CardHeader title="Memberships" subtitle={`You belong to ${memberships.length} trust${memberships.length === 1 ? '' : 's'}`} />
          <div className="divide-y divide-stone-100">
            {memberships.map((m) => (
              <div key={m.trustId} className="flex items-center gap-3 p-4">
                <div className="flex h-10 w-10 items-center justify-center overflow-hidden rounded-xl bg-saffron-100 text-sm font-bold text-saffron-700">
                  {m.trust.logoUrl ? <img src={m.trust.logoUrl} alt="" className="h-full w-full object-cover" /> : m.trust.name[0]}
                </div>
                <div className="min-w-0 flex-1">
                  <p className="font-semibold text-stone-800">{m.trust.name}</p>
                  <p className="text-xs text-stone-500">{ROLE_LABELS[m.role as keyof typeof ROLE_LABELS] ?? m.role} · {formatDate(m.joinedAt)}</p>
                </div>
                <button onClick={() => { useAuth.getState().setActiveTrust(m.trustId); navigate('/app') }} className="text-sm font-semibold text-saffron-600 hover:underline">Open →</button>
              </div>
            ))}
          </div>
        </Card>

        <Card className="mt-5">
          <CardHeader title="My donations" action={<Button variant="outline" size="sm" onClick={loadDonations}>Load</Button>} />
          <div className="p-4">
            {donations.length === 0 ? (
              <p className="py-4 text-center text-sm text-stone-400">{loaded ? 'No donations found for your contact.' : 'Load your donation history to see receipts.'}</p>
            ) : (
              <div className="space-y-2">
                {donations.map((d) => (
                  <div key={d.id} className="flex items-center justify-between rounded-xl border border-stone-100 p-3 text-sm">
                    <div className="flex items-center gap-3">
                      <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-maroon-50 text-maroon-600"><Heart className="h-4 w-4" /></div>
                      <div>
                        <p className="font-medium text-stone-800">{d.trust?.name ?? '—'}</p>
                        <p className="text-xs text-stone-400">{new Date(d.donationDate).toLocaleDateString()} · {d.category}</p>
                      </div>
                    </div>
                    <div className="text-right">
                      <p className="font-bold text-maroon-700">₹{d.amount.toLocaleString('en-IN')}</p>
                      {d.receipts?.[0] && (
                        <a href={`/api/v1/receipts/receipts/${d.receipts[0].id}/pdf`} target="_blank" rel="noreferrer" className="text-xs font-semibold text-saffron-600 hover:underline">Receipt</a>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </Card>

        <Button variant="danger" className="mt-5 w-full" onClick={logout}><LogOut className="h-4 w-4" /> Log out</Button>
      </div>
    </div>
  )
}

