import { type ReceiptData, type ReceiptTemplateView, FONT_CSS, pagePx } from './types.js'
import { buildDrawOps, type MeasureFn } from './layout.js'

export interface CanvasRenderInput {
  template: ReceiptTemplateView
  data: ReceiptData
  background?: HTMLImageElement | HTMLCanvasElement | null
  logo?: HTMLImageElement | HTMLCanvasElement | null
  qr?: HTMLImageElement | HTMLCanvasElement | null
  scale?: number
}

export async function renderReceiptToCanvas(input: CanvasRenderInput): Promise<HTMLCanvasElement> {
  const { template, data, background, logo, qr, scale = 2 } = input
  const page = pagePx(template.pageSize, template.widthMm, template.heightMm)

  const canvas = document.createElement('canvas')
  canvas.width = Math.round(page.width * scale)
  canvas.height = Math.round(page.height * scale)
  const ctx = canvas.getContext('2d')!
  ctx.scale(scale, scale)
  ctx.clearRect(0, 0, page.width, page.height)

  if (background) {
    drawCover(ctx, background, page.width, page.height)
  } else {
    ctx.fillStyle = '#fffdf5'
    ctx.fillRect(0, 0, page.width, page.height)
    ctx.strokeStyle = '#d4af37'
    ctx.lineWidth = 2
    ctx.strokeRect(3, 3, page.width - 6, page.height - 6)
    ctx.strokeStyle = '#7f1d1d'
    ctx.lineWidth = 1
    ctx.strokeRect(7, 7, page.width - 14, page.height - 14)
  }

  const measure: MeasureFn = (text, size, bold) => {
    const key = bold ? 'Mukta-Bold' : 'Mukta'
    const css = FONT_CSS[key]
    ctx.font = `${css.weight} ${size}px "${css.family}", sans-serif`
    return ctx.measureText(text).width
  }

  const { ops } = buildDrawOps(template, data, {
    logoImage: logo ?? null,
    qrImage: qr ?? null,
    measure,
  })

  for (const op of ops) {
    if (op.kind === 'line') {
      ctx.strokeStyle = '#4a1f0c'
      ctx.lineWidth = 1
      ctx.beginPath()
      ctx.moveTo(op.x, op.y)
      ctx.lineTo(op.x + op.width, op.y)
      ctx.stroke()
      continue
    }
    if (op.kind === 'image') {
      const img = op.value === 'qr' ? qr : logo
      if (!img) continue
      const h = op.height
      const w = h * imgHeightToWidth(img)
      let x = op.x
      if (op.align === 'center') x = op.x + (op.width - w) / 2
      else if (op.align === 'right') x = op.x + op.width - w
      ctx.drawImage(img, x, op.y, w, h)
      continue
    }
    if (op.kind !== 'text' || !op.value) continue
    const css = (FONT_CSS as Record<string, { family: string; weight: number }>)[op.fontFamily] ?? FONT_CSS.Mukta
    ctx.font = `${css.weight} ${op.fontSize}px "${css.family}", sans-serif`
    ctx.fillStyle = op.color
    ctx.globalAlpha = op.alpha ?? 1
    const tw = ctx.measureText(op.value).width
    let x = op.x
    if (op.align === 'center') x = op.x + (op.width - tw) / 2
    else if (op.align === 'right') x = op.x + op.width - tw
    ctx.textBaseline = 'alphabetic'
    ctx.fillText(op.value, x, op.y + op.fontSize * 0.85)
    ctx.globalAlpha = 1
  }

  return canvas
}

function imgHeightToWidth(img: HTMLImageElement | HTMLCanvasElement): number {
  const nw = 'naturalWidth' in img ? img.naturalWidth : img.width
  const nh = 'naturalHeight' in img ? img.naturalHeight : img.height
  return nw && nh ? nw / nh : 1
}

function drawCover(ctx: CanvasRenderingContext2D, img: HTMLImageElement | HTMLCanvasElement, w: number, h: number): void {
  const iw = 'naturalWidth' in img ? img.naturalWidth : img.width
  const ih = 'naturalHeight' in img ? img.naturalHeight : img.height
  const imgRatio = iw / ih
  const pageRatio = w / h
  let dw = w
  let dh = h
  if (imgRatio > pageRatio) {
    dh = w / imgRatio
  } else {
    dw = h * imgRatio
  }
  ctx.drawImage(img, (w - dw) / 2, (h - dh) / 2, dw, dh)
}

export async function canvasToBlob(canvas: HTMLCanvasElement, type = 'image/png'): Promise<Blob> {
  return new Promise((resolve, reject) => {
    canvas.toBlob((b) => (b ? resolve(b) : reject(new Error('canvas toBlob failed'))), type)
  })
}

import { amountInWords, formatDate, PAYMENT_MODE_LABELS, type PaymentMode } from '@pavati/shared'
import { FONT_CACHE } from './fonts.js'
import { type DrawOp, type ReceiptData, type ReceiptTemplateView } from './types.js'
import { normalizeFont, pagePx } from './types.js'

function formatAmount(n: number): string {
  return new Intl.NumberFormat('en-IN', { maximumFractionDigits: 2 }).format(n)
}

export function buildFieldValues(data: ReceiptData): Record<string, string> {
  const mode = data.paymentMode as PaymentMode
  return {
    trustName: data.trustName,
    trustAddress: data.trustAddress ?? '',
    receiptNumber: data.receiptNumber,
    receiptDate: formatDate(data.receiptDate),
    donorName: data.donorName,
    donorPhone: data.donorPhone ?? '',
    donorAddress: data.donorAddress ?? '',
    amount: formatAmount(data.amount),
    amountInWords: amountInWords(data.amount),
    paymentMode: PAYMENT_MODE_LABELS[mode] ?? data.paymentMode,
    donationCategory: data.category,
    transactionRef: data.transactionRef ?? '',
    collectorName: data.collectorName ?? '',
    signature: 'Authorized Signature',
    footerText: data.footerText ?? `धन्यवाद — Thank you for your generous support`,
    qrCode: '',
    logo: '',
  }
}

export interface MeasureFn {
  (text: string, size: number, bold: boolean): number
}

export function wrapText(text: string, measure: MeasureFn, size: number, bold: boolean, maxWidth: number): string[] {
  const clean = text.replace(/\s+/g, ' ').trim()
  if (!clean) return []
  const words = clean.split(' ')
  const lines: string[] = []
  let current = ''
  for (const word of words) {
    const candidate = current ? `${current} ${word}` : word
    if (current && measure(candidate, size, bold) > maxWidth) {
      lines.push(current)
      current = word
    } else {
      current = candidate
    }
  }
  if (current) lines.push(current)
  return lines
}

export interface BuildDrawOpts {
  logoImage?: HTMLImageElement | HTMLCanvasElement | ImageBitmap | null
  qrImage?: HTMLImageElement | HTMLCanvasElement | ImageBitmap | null
  measure?: MeasureFn
}

export function buildDrawOps(
  template: ReceiptTemplateView,
  data: ReceiptData,
  opts: BuildDrawOpts = {}
): { ops: DrawOp[]; page: { width: number; height: number } } {
  const page = pagePx(template.pageSize, template.widthMm, template.heightMm)
  const values = buildFieldValues(data)
  const ops: DrawOp[] = []
  const refWidth = 794

  const measure: MeasureFn =
    opts.measure ??
    ((text: string, size: number, bold: boolean) => {
      const fam = bold ? 'Mukta-Bold' : 'Mukta'
      const font = FONT_CACHE[fam]
      if (font) return font.widthOfTextAtSize(text, size)
      return text.length * size * 0.55
    })

  for (const f of template.fieldConfigs ?? []) {
    if (!f.visible) continue
    const scale = page.width / refWidth
    const x = (f.x / 100) * page.width
    const y = (f.y / 100) * page.height
    const width = (f.width / 100) * page.width
    const height = (f.height / 100) * page.height
    const fontSize = Math.max(4, f.fontSize * scale)
    const fontKey = normalizeFont(f.fontFamily)

    if (f.key === 'qrCode') {
      ops.push({ kind: 'image', value: 'qr', image: opts.qrImage ?? null, x, y, width, height, fontSize, fontFamily: fontKey, color: f.color, align: f.align, bold: f.bold })
      continue
    }
    if (f.key === 'logo') {
      ops.push({ kind: 'image', value: 'logo', image: opts.logoImage ?? null, x, y, width, height, fontSize, fontFamily: fontKey, color: f.color, align: f.align, bold: f.bold })
      continue
    }

    let raw = values[f.key] ?? ''
    if (!raw) continue
    let prefix = f.prefix ?? ''
    let text = `${prefix}${raw}`
    if (f.key === 'amount') text = `₹ ${raw}`

    if (f.key === 'signature') {
      const lineY = y + height * 0.6
      ops.push({ kind: 'line', x, y: lineY, width, height: 1, fontSize, fontFamily: fontKey, color: '#4a1f0c', align: f.align, bold: false })
      ops.push({ kind: 'text', value: 'Authorized Signature', x, y: lineY + fontSize * 1.1, width, height: fontSize, fontSize: Math.max(8, fontSize * 0.85), fontFamily: 'Mukta', color: '#6b4a2b', align: 'center', bold: false })
      continue
    }

    if (f.key === 'footerText') {
      ops.push({ kind: 'text', value: text, x, y, width, height, fontSize, fontFamily: fontKey, color: f.color, align: f.align, bold: f.bold, alpha: 0.75 })
      continue
    }

    const lines = wrapText(text, measure, fontSize, f.bold, width)
    let ly = y
    for (const line of lines) {
      ops.push({ kind: 'text', value: line, x, y: ly, width, height: fontSize, fontSize, fontFamily: fontKey, color: f.color, align: f.align, bold: f.bold })
      ly += fontSize * 1.22
    }
  }

  return { ops, page }
}

