import { useEffect, useRef, useState } from 'react'
import { renderReceiptToCanvas } from '@pavati/receipt-engine'
import type { ReceiptTemplateView } from '@pavati/receipt-engine'
import { Spinner } from './ui'

function loadImage(url: string): Promise<HTMLImageElement> {
  return new Promise((resolve, reject) => {
    const img = new Image()
    img.crossOrigin = 'anonymous'
    img.onload = () => resolve(img)
    img.onerror = () => reject(new Error(`Failed to load image: ${url}`))
    img.src = url
  })
}

export interface PreviewData {
  trustName: string
  trustAddress?: string
  receiptNumber: string
  receiptDate: string
  donorName: string
  donorPhone?: string
  donorAddress?: string
  amount: number
  category: string
  paymentMode: string
  transactionRef?: string
  collectorName?: string
  footerText?: string
}

export function ReceiptCanvasPreview({
  template,
  data,
  scale = 1.6,
  className,
}: {
  template: ReceiptTemplateView
  data: PreviewData
  scale?: number
  className?: string
}) {
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    let cancelled = false
    ;(async () => {
      setError(null)
      try {
        const [bg, logo] = await Promise.all([
          template.backgroundImageUrl ? loadImage(template.backgroundImageUrl) : Promise.resolve(null),
          template.logoUrl ? loadImage(template.logoUrl) : Promise.resolve(null),
        ])
        if (cancelled) return
        const canvas = await renderReceiptToCanvas({
          template: { ...template, logoUrl: null },
          data: data as any,
          background: bg ?? undefined,
          logo: logo ?? undefined,
          scale,
        })
        if (canvasRef.current) {
          canvasRef.current.replaceWith(canvas)
        }
      } catch (e: any) {
        if (!cancelled) setError(e.message)
      }
    })()
    return () => {
      cancelled = true
    }
  }, [template, data, scale])

  if (error) return <div className="flex h-40 items-center justify-center text-sm text-red-600">{error}</div>
  return (
    <div className="flex flex-col items-center gap-2">
      {!canvasRef.current && <Spinner label="Rendering preview…" />}
      <canvas ref={canvasRef} className={className} />
    </div>
  )
}

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { Link } from 'react-router-dom'
import { FileText, PlusCircle, Trash2, CheckCircle2, Palette } from 'lucide-react'
import { toast } from 'sonner'
import { api } from '../../lib/api'
import { AppLayout } from '../../components/layout'
import { Card, Badge, Spinner, EmptyState, PageHeader, Button } from '../../components/ui'
import { useActiveTrust } from '../../lib/stores/auth'

export default function TemplatesPage() {
  const active = useActiveTrust()!
  const qc = useQueryClient()

  const { data, isLoading } = useQuery({
    queryKey: ['templates', active.trustId],
    queryFn: () => api.get<any[]>(`/trusts/${active.trustId}/templates`),
  })

  const activate = useMutation({
    mutationFn: (id: string) => api.post(`/trusts/${active.trustId}/templates/${id}/activate`),
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: ['templates', active.trustId] })
      toast.success('Template activated')
    },
    onError: (e: any) => toast.error(e.message),
  })

  const del = useMutation({
    mutationFn: (id: string) => api.del(`/trusts/${active.trustId}/templates/${id}`),
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: ['templates', active.trustId] })
      toast.success('Template deleted')
    },
    onError: (e: any) => toast.error(e.message),
  })

  return (
    <AppLayout>
      <PageHeader title="Pāvati Templates" subtitle="Design and manage your receipt layouts" action={<Link to="/app/templates/new" className="btn-primary"><PlusCircle className="h-4 w-4" /> New template</Link>} />
      {isLoading || !data ? <Spinner /> : data.length === 0 ? (
        <Card><EmptyState icon={<FileText className="h-6 w-6" />} title="No templates yet" description="Create a template to design your Pāvati receipts." action={<Link to="/app/templates/new" className="btn-primary"><PlusCircle className="h-4 w-4" /> New template</Link>} /></Card>
      ) : (
        <div className="grid gap-5 sm:grid-cols-2 lg:grid-cols-3">
          {data.map((t) => (
            <Card key={t.id} className="overflow-hidden">
              <div className="flex h-44 items-center justify-center bg-gradient-to-br from-saffron-50 to-cream-100 p-4">
                <div className="h-full max-h-40 w-full overflow-hidden rounded-lg shadow-sm" style={{ backgroundImage: t.backgroundImageUrl ? `url(${t.backgroundImageUrl})` : undefined, backgroundSize: 'cover', backgroundPosition: 'center' }}>
                  <div className="flex h-full flex-col items-center justify-center gap-1 bg-black/10 p-2 text-center">
                    <span className="rounded bg-white/70 px-2 py-0.5 text-[10px] font-bold text-maroon-700">{t.name}</span>
                    <span className="text-[9px] text-white drop-shadow">Receipt No · Date · Amount</span>
                  </div>
                </div>
              </div>
              <div className="p-4">
                <div className="flex items-center justify-between">
                  <p className="font-semibold text-stone-900">{t.name}</p>
                  {t.active ? <Badge color="green"><CheckCircle2 className="h-3 w-3" /> Active</Badge> : <Badge>Inactive</Badge>}
                </div>
                <p className="mt-0.5 text-xs text-stone-400">{t.pageSize}{t.pageSize === 'CUSTOM' ? ` (${t.widthMm}×${t.heightMm}mm)` : ''} · {t.fieldConfigs?.length ?? 0} fields</p>
                <div className="mt-3 flex items-center gap-2">
                  <Link to={`/app/templates/${t.id}/edit`} className="btn-outline flex-1 py-2 text-xs"><Palette className="h-3.5 w-3.5" /> Edit</Link>
                  {!t.active && <Button size="sm" variant="outline" onClick={() => activate.mutate(t.id)}>Activate</Button>}
                  <Button size="sm" variant="ghost" className="text-red-600" onClick={() => confirm('Delete this template?') && del.mutate(t.id)}><Trash2 className="h-4 w-4" /></Button>
                </div>
              </div>
            </Card>
          ))}
        </div>
      )}
    </AppLayout>
  )
}

import { useEffect, useMemo, useState } from 'react'
import { useNavigate, useParams, Link } from 'react-router-dom'
import { toast } from 'sonner'
import { ArrowLeft, Save, Plus, Eye, EyeOff, Upload } from 'lucide-react'
import { DEFAULT_FIELDS, FIELD_LABELS, type ReceiptFieldConfig, ReceiptCanvasPreview } from '@pavati/receipt-engine'
import { PAGE_SIZE_MM, type PageSize } from '@pavati/shared'
import { api, uploadFile } from '../../lib/api'
import { AppLayout } from '../../components/layout'
import { Button, Card, CardHeader, Input, Select } from '../../components/ui'
import { useActiveTrust } from '../../lib/stores/auth'
import { fileToDataUrl } from '../../lib/utils'

const SAMPLE: any = {
  trustName: 'Shree Ganesh Mitra Mandal',
  trustAddress: 'Ganesh Mandir Road, Kothrud, Pune, 411038',
  receiptNumber: 'RC-2026-000001',
  receiptDate: new Date().toISOString(),
  donorName: 'Rajesh Patil',
  donorPhone: '9876543210',
  amount: 501,
  category: 'Ganpati Donation',
  paymentMode: 'CASH',
  collectorName: 'Sanjay Kulkarni',
}

export default function TemplateEditorPage() {
  const { templateId } = useParams()
  const isNew = templateId === 'new' || !templateId
  const navigate = useNavigate()
  const active = useActiveTrust()!
  const [loading, setLoading] = useState(!isNew)
  const [saving, setSaving] = useState(false)
  const [name, setName] = useState('')
  const [pageSize, setPageSize] = useState<PageSize>('CUSTOM')
  const [widthMm, setWidthMm] = useState(148)
  const [heightMm, setHeightMm] = useState(83)
  const [bgUrl, setBgUrl] = useState<string | null>(null)
  const [fields, setFields] = useState<ReceiptFieldConfig[]>(DEFAULT_FIELDS.map((f) => ({ ...f })))

  useEffect(() => {
    if (isNew) return
    api.get<any>(`/trusts/${active.trustId}/templates/${templateId}`).then((t) => {
      setName(t.name)
      setPageSize(t.pageSize)
      setWidthMm(t.widthMm ?? 148)
      setHeightMm(t.heightMm ?? 83)
      setBgUrl(t.backgroundImageUrl)
      if (t.fieldConfigs?.length) setFields(t.fieldConfigs)
    }).finally(() => setLoading(false))
  }, [templateId, active.trustId])

  const template = useMemo(() => ({
    id: templateId ?? 'preview',
    name,
    pageSize,
    widthMm,
    heightMm,
    backgroundImageUrl: bgUrl,
    fieldConfigs: fields,
  }), [name, pageSize, widthMm, heightMm, bgUrl, fields])

  const updateField = (i: number, patch: Partial<ReceiptFieldConfig>) => {
    setFields((prev) => prev.map((f, idx) => (idx === i ? { ...f, ...patch } : f)))
  }

  const addField = () => {
    const used = new Set(fields.map((f) => f.key))
    const key = (Object.keys(FIELD_LABELS) as (keyof typeof FIELD_LABELS)[]).find((k) => !used.has(k))
    if (!key) return toast.info('All fields are already added')
    setFields([...fields, { key, label: FIELD_LABELS[key], x: 4, y: 90, width: 40, height: 7, fontSize: 14, fontFamily: 'Mukta', color: '#4a1f0c', align: 'left', bold: false, visible: true }])
  }

  const onBg = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (!file) return
    const dataUrl = await fileToDataUrl(file)
    const res = await uploadFile(dataUrl)
    setBgUrl(res.url)
    toast.success('Background uploaded')
  }

  const save = async () => {
    if (!name.trim()) return toast.error('Template needs a name')
    setSaving(true)
    const body = { name, pageSize, widthMm: pageSize === 'CUSTOM' ? widthMm : null, heightMm: pageSize === 'CUSTOM' ? heightMm : null, backgroundImageUrl: bgUrl, fieldConfigs: fields }
    try {
      if (isNew) {
        await api.post(`/trusts/${active.trustId}/templates`, body)
        toast.success('Template created')
      } else {
        await api.patch(`/trusts/${active.trustId}/templates/${templateId}`, body)
        toast.success('Template saved')
      }
      navigate('/app/templates')
    } catch (e: any) {
      toast.error(e.message)
    } finally {
      setSaving(false)
    }
  }

  const [selected, setSelected] = useState<number | null>(null)
  const sel = selected !== null ? fields[selected] : null

  return (
    <AppLayout>
      {loading ? <div className="py-10 text-center text-stone-400">Loading…</div> : (
        <>
          <div className="mb-6 flex flex-wrap items-center justify-between gap-3">
            <div>
              <Link to="/app/templates" className="mb-1 inline-flex items-center gap-2 text-sm text-stone-500 hover:text-stone-700"><ArrowLeft className="h-4 w-4" /> Back to templates</Link>
              <h1 className="text-2xl font-bold text-stone-900">{isNew ? 'New template' : `Edit: ${name}`}</h1>
            </div>
            <Button onClick={save} loading={saving}><Save className="h-4 w-4" /> Save template</Button>
          </div>

          <div className="grid gap-6 lg:grid-cols-2">
            <div className="space-y-5">
              <Card>
                <CardHeader title="Template settings" />
                <div className="space-y-4 p-5">
                  <div><label className="label">Template name</label><Input value={name} onChange={(e) => setName(e.target.value)} placeholder="e.g. Ganeshotsav 2026" /></div>
                  <div className="grid grid-cols-3 gap-3">
                    {Object.entries(PAGE_SIZE_MM).map(([key, mm]) => (
                      <button key={key} onClick={() => { setPageSize(key as PageSize); if (key !== 'CUSTOM') { setWidthMm(mm.width); setHeightMm(mm.height) } }}
                        className={`rounded-xl border px-3 py-2.5 text-sm font-semibold ${pageSize === key ? 'border-saffron-500 bg-saffron-50 text-saffron-700' : 'border-stone-200 text-stone-600 hover:border-stone-300'}`}>
                        {key === 'CUSTOM' ? `Custom\n(${widthMm}×${heightMm})` : `${key} (${mm.width}×${mm.height}mm)`}
                      </button>
                    ))}
                  </div>
                  {pageSize === 'CUSTOM' && (
                    <div className="grid grid-cols-2 gap-3">
                      <div><label className="label">Width (mm)</label><Input type="number" value={widthMm} onChange={(e) => setWidthMm(Number(e.target.value))} /></div>
                      <div><label className="label">Height (mm)</label><Input type="number" value={heightMm} onChange={(e) => setHeightMm(Number(e.target.value))} /></div>
                    </div>
                  )}
                  <div>
                    <label className="label">Background image</label>
                    <div className="flex items-center gap-3">
                      <div className="h-14 w-24 overflow-hidden rounded-lg border border-stone-200" style={{ backgroundImage: bgUrl ? `url(${bgUrl})` : undefined, backgroundSize: 'cover' }} />
                      <label className="cursor-pointer"><span className="btn-outline"><Upload className="h-4 w-4" /> Upload</span><input type="file" accept="image/*" className="hidden" onChange={onBg} /></label>
                      {bgUrl && <button onClick={() => setBgUrl(null)} className="text-xs text-red-600 hover:underline">Remove</button>}
                    </div>
                  </div>
                </div>
              </Card>

              <Card>
                <CardHeader title="Fields" action={<Button size="sm" variant="outline" onClick={addField}><Plus className="h-4 w-4" /> Add</Button>} />
                <div className="max-h-80 space-y-1 overflow-y-auto p-3">
                  {fields.map((f, i) => (
                    <button key={`${f.key}-${i}`} onClick={() => setSelected(selected === i ? null : i)}
                      className={`flex w-full items-center justify-between rounded-lg px-3 py-2 text-left text-sm ${selected === i ? 'bg-saffron-50 text-saffron-700' : 'text-stone-700 hover:bg-stone-50'}`}>
                      <span className="font-medium">{f.label}</span>
                      <span className="flex items-center gap-2 text-xs text-stone-400">
                        {f.visible ? <Eye className="h-3.5 w-3.5" /> : <EyeOff className="h-3.5 w-3.5" />}
                        {Math.round(f.x)}%, {Math.round(f.y)}%
                      </span>
                    </button>
                  ))}
                </div>
              </Card>
            </div>

            <div className="space-y-5">
              <div className="rounded-2xl border border-stone-200 bg-white p-4">
                <p className="mb-3 text-sm font-semibold text-stone-500">Live preview</p>
                <ReceiptCanvasPreview template={template} data={SAMPLE} scale={1.4} className="mx-auto max-w-full rounded-lg shadow" />
              </div>

              {sel && (
                <Card>
                  <CardHeader title={`Edit: ${sel.label}`} action={<Button size="sm" variant="ghost" onClick={() => updateField(selected!, { visible: !sel.visible })}>{sel.visible ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}</Button>} />
                  <div className="grid grid-cols-2 gap-3 p-5 sm:grid-cols-3">
                    <div><label className="label">X %</label><Input type="number" value={sel.x} onChange={(e) => updateField(selected!, { x: Number(e.target.value) })} /></div>
                    <div><label className="label">Y %</label><Input type="number" value={sel.y} onChange={(e) => updateField(selected!, { y: Number(e.target.value) })} /></div>
                    <div><label className="label">Width %</label><Input type="number" value={sel.width} onChange={(e) => updateField(selected!, { width: Number(e.target.value) })} /></div>
                    <div><label className="label">Height %</label><Input type="number" value={sel.height} onChange={(e) => updateField(selected!, { height: Number(e.target.value) })} /></div>
                    <div><label className="label">Font size</label><Input type="number" value={sel.fontSize} onChange={(e) => updateField(selected!, { fontSize: Number(e.target.value) })} disabled={sel.key === 'logo' || sel.key === 'qrCode'} /></div>
                    <div><label className="label">Align</label>
                      <Select value={sel.align} onChange={(e) => updateField(selected!, { align: e.target.value as any })}>
                        <option value="left">Left</option><option value="center">Center</option><option value="right">Right</option>
                      </Select>
                    </div>
                    <div><label className="label">Weight</label>
                      <Select value={sel.fontFamily} onChange={(e) => updateField(selected!, { fontFamily: e.target.value })}>
                        <option value="Mukta">Regular</option><option value="Mukta-Medium">Medium</option>
                        <option value="Mukta-SemiBold">SemiBold</option><option value="Mukta-Bold">Bold</option>
                      </Select>
                    </div>
                    <div><label className="label">Color</label><input type="color" value={sel.color} onChange={(e) => updateField(selected!, { color: e.target.value })} className="h-10 w-full cursor-pointer rounded-lg border border-stone-300" /></div>
                    <div><label className="label">Prefix</label><Input value={sel.prefix ?? ''} onChange={(e) => updateField(selected!, { prefix: e.target.value })} placeholder="e.g. Date: " /></div>
                    {selected !== null && (
                      <div className="col-span-2 flex items-end">
                        <Button size="sm" variant="danger" onClick={() => setFields((prev) => prev.filter((_, i) => i !== selected))}>Remove field</Button>
                      </div>
                    )}
                  </div>
                </Card>
              )}
            </div>
          </div>
        </>
      )}
    </AppLayout>
  )
}

