import { describe, expect, it } from 'vitest'
import { permissionsForRole, ROLE_PERMISSIONS, ALL_PERMISSIONS } from '@pavati/shared'

describe('ROLE_PERMISSIONS', () => {
  it('primary admin gets every permission', () => {
    expect(ROLE_PERMISSIONS.PRIMARY_ADMIN).toEqual(ALL_PERMISSIONS)
  })

  it('collector can create donations and receipts but not manage templates or audit', () => {
    const p = permissionsForRole('COLLECTOR')
    expect(p).toContain('donation:create')
    expect(p).toContain('receipt:create')
    expect(p).not.toContain('template:manage')
    expect(p).not.toContain('audit:view')
    expect(p).not.toContain('donation:view')
  })

  it('every member role can view donations, receipts and announcements', () => {
    for (const role of ['MEMBER', 'VOLUNTEER', 'COLLECTOR', 'TREASURER', 'SECRETARY', 'PRESIDENT', 'ADMIN'] as const) {
      const p = permissionsForRole(role)
      expect(p).toContain('donation:view')
      expect(p).toContain('receipt:view')
      expect(p).toContain('announcement:view')
    }
  })

  it('only admin roles can manage templates', () => {
    expect(permissionsForRole('ADMIN')).toContain('template:manage')
    expect(permissionsForRole('TREASURER')).not.toContain('template:manage')
    expect(permissionsForRole('SECRETARY')).not.toContain('template:manage')
  })

  it('falls back to the everyone set for unknown roles', () => {
    expect(permissionsForRole('GHOST' as never)).toContain('trust:view')
    expect(permissionsForRole('GHOST' as never)).not.toContain('template:manage')
  })
})

import { describe, expect, it } from 'vitest'
import { createDonationSchema, createOnlineDonationSchema, createTemplateSchema, registerSchema, verifyOtpSchema } from '@pavati/shared'

describe('createDonationSchema', () => {
  const base = {
    trustId: '096dd518-28fe-4b70-8ea9-2a6a0aea0252',
    donorName: 'Rajesh Patil',
    amount: 501,
    category: 'Ganpati Donation',
    paymentMode: 'CASH',
  }

  it('accepts a valid donation', () => {
    expect(createDonationSchema.parse(base)).toMatchObject({ privacy: 'PRIVATE' })
  })

  it('rejects a missing trustId', () => {
    const { trustId, ...rest } = base
    expect(() => createDonationSchema.parse(rest)).toThrow(/trustId/)
  })

  it('rejects non-positive amounts', () => {
    expect(() => createDonationSchema.parse({ ...base, amount: 0 })).toThrow()
    expect(() => createDonationSchema.parse({ ...base, amount: -5 })).toThrow()
  })

  it('rejects an invalid 10-digit phone', () => {
    expect(() => createDonationSchema.parse({ ...base, phone: '12345' })).toThrow()
    expect(() => createDonationSchema.parse({ ...base, phone: '9876543210' })).not.toThrow()
  })
})

describe('createOnlineDonationSchema', () => {
  const base = {
    trustId: '096dd518-28fe-4b70-8ea9-2a6a0aea0252',
    amount: 1100,
    category: 'Ganpati Donation',
  }

  it('accepts an anonymous online donation without contact details', () => {
    const out = createOnlineDonationSchema.parse({ ...base, anonymous: true })
    expect(out.anonymous).toBe(true)
  })

  it('requires a name when not anonymous', () => {
    expect(() => createOnlineDonationSchema.parse({ ...base, anonymous: false })).not.toThrow()
  })

  it('validates email format when provided', () => {
    expect(() => createOnlineDonationSchema.parse({ ...base, email: 'nope' })).toThrow()
    expect(() => createOnlineDonationSchema.parse({ ...base, email: 'donor@test.in' })).not.toThrow()
  })
})

describe('createTemplateSchema', () => {
  const field = {
    key: 'donorName',
    label: 'Donor Name',
    x: 4,
    y: 42,
    width: 60,
    height: 8,
    fontSize: 19,
    fontFamily: 'Mukta-Bold',
    color: '#4a1f0c',
    align: 'left',
    bold: true,
    visible: true,
  }

  it('accepts a template with fields', () => {
    const out = createTemplateSchema.parse({ name: 'Ganeshotsav', fieldConfigs: [field] })
    expect(out.pageSize).toBe('A5')
    expect(out.fieldConfigs).toHaveLength(1)
  })

  it('rejects coordinates outside 0-100', () => {
    expect(() => createTemplateSchema.parse({ name: 'Bad', fieldConfigs: [{ ...field, x: 150 }] })).toThrow()
  })

  it('rejects a short name', () => {
    expect(() => createTemplateSchema.parse({ name: 'A' })).toThrow()
  })
})

describe('registerSchema & verifyOtpSchema', () => {
  it('requires a strong enough password', () => {
    expect(() => registerSchema.parse({ name: 'Test User', email: 't@test.in', password: '123' })).toThrow()
    expect(() => registerSchema.parse({ name: 'Test User', email: 't@test.in', password: '123456' })).not.toThrow()
  })

  it('requires a 6-digit OTP', () => {
    expect(verifyOtpSchema.parse({ phone: '9876543210', otp: '123456' })).toBeTruthy()
    expect(() => verifyOtpSchema.parse({ phone: '9876543210', otp: '12ab' })).toThrow()
  })
})

import { describe, expect, it, beforeAll, afterAll } from 'vitest'
import request from 'supertest'
import type { Express } from 'express'
import { createApp } from '../index.js'

let app: Express

beforeAll(() => {
  process.env.NODE_ENV = 'test'
  app = createApp()
})

afterAll(async () => {
  const { prisma } = await import('../lib/prisma.js')
  await prisma.$disconnect()
})

describe('app smoke', () => {
  it('serves /health without auth', async () => {
    const res = await request(app).get('/health')
    expect(res.status).toBe(200)
    expect(res.body.ok).toBe(true)
  })

  it('returns 401 for protected routes without a token', async () => {
    expect((await request(app).get('/api/v1/auth/me')).status).toBe(401)
    expect((await request(app).get('/api/v1/trusts/096dd518-28fe-4b70-8ea9-2a6a0aea0252/donations')).status).toBe(401)
  })

  it('rejects malformed login bodies with 400', async () => {
    const res = await request(app).post('/api/v1/auth/login').send({ email: 'not-an-email', password: '123' })
    expect(res.status).toBe(400)
    expect(res.body.error).toBe('Validation failed')
  })

  it('rejects a weak registration password with 400', async () => {
    const res = await request(app)
      .post('/api/v1/auth/register')
      .send({ name: 'Test User', email: 't@test.in', password: 'abc' })
    expect(res.status).toBe(400)
  })

  it('returns 404 for unknown routes', async () => {
    expect((await request(app).get('/api/v1/nope')).status).toBe(404)
  })
})

