import { prisma } from '/home/dedsec/Projects/pavatiApp/apps/api/src/lib/prisma.js'
import { generateReceipt } from '/home/dedsec/Projects/pavatiApp/apps/api/src/services/receipts.js'

const TRUST_ID = 'ede0cd02-7e5f-4d61-9a44-1b37cd023ede'

const member = await prisma.trustMember.findFirst({ where: { trustId: TRUST_ID, status: 'ACTIVE' } })
const trust = await prisma.trust.findUnique({ where: { id: TRUST_ID } })

const donation = await prisma.donation.create({
  data: {
    trustId: TRUST_ID,
    donorName: 'Repro Temp Donor',
    phone: '9876543210',
    amount: 501,
    category: 'Ganpati Donation',
    paymentMode: 'CASH',
    donationDate: new Date(),
    collectorId: member?.id,
    status: 'SUCCEEDED',
    isOnline: false,
  },
})
console.log('temp donation:', donation.id)

try {
  const out = await generateReceipt({
    donationId: donation.id,
    trust,
    donation,
    collector: member,
    collectorName: 'Repro User',
    actorId: member?.userId ?? '00000000-0000-0000-0000-000000000000',
  })
  console.log('RECEIPT OK:', JSON.stringify(out))
} catch (e) {
  console.error('GENERATE FAILED:', e.constructor?.name, JSON.stringify({ status: e.statusCode ?? e.status, message: e.message }))
